/* daily-mocks.js — full-length timed SSC CGL English mocks (25Q, exam mode).
   Source: september_30_test1/test2 (fixed + deduped against each other).
   Schema matches BANK/PYQ: {q, options[4], answer, explanation, rule, trapcat, level}. */
const DAILY_MOCKS = [
{
  id: "sept30_m1", label: "30 Sep · Morning Full Mock", timeLimitMin: 20,
  questions: [
    { q: "The committee has decided to postpone the meeting due to unavoidable circumstances.", options: ["The committee has decided", "to postpone the meeting", "due to unavoidable circumstances", "No error"], answer: 3, explanation: "Committee is a collective noun acting as a single unit, taking singular verb 'has'.", rule: "Collective noun acting as one unit → singular verb (has, is, was).", trapcat: "Subject-verb agreement", level: "L1 Direct" },
    { q: "One of the highest peaks in the Himalayas is Kanchenjunga.", options: ["One of the highest peaks", "in the Himalayas is", "Kanchenjunga", "No error"], answer: 3, explanation: "'One of + plural noun' → verb is singular. SSC trick: students see 'Himalayas' and expect a plural verb, but the true subject is 'one'.", rule: "One of + plural noun → singular verb.", trapcat: "One of + plural (common error)", level: "L1 Direct" },
    { q: "The hunter as well as the guides were tracking the tiger.", options: ["The hunter", "as well as the guides", "were tracking the tiger", "No error"], answer: 1, explanation: "'As well as' does not pluralise the subject; hunter stays singular → was tracking.", rule: "R4 — as well as does not make subject plural.", trapcat: "As well as trap", level: "L2 Application" },
    { q: "The list of items is missing from the inventory.", options: ["The list of items", "is missing from the inventory", "No error"], answer: 2, explanation: "The list is singular; 'of items' is a prepositional phrase that does not change the subject.", rule: "R1 — verb follows the real subject, ignore prepositional phrases.", trapcat: "Intervenient phrase", level: "L2 Application" },
    { q: "Either the manager or his staff is responsible for this mistake.", options: ["Either the manager or his staff", "is responsible for this mistake", "No error"], answer: 2, explanation: "Either/or → verb agrees with the NEARER subject. 'Staff' is closer to the verb, and here is/singular works either way — correct as written.", rule: "R2 — either/or, neither/nor → nearer subject.", trapcat: "Either/neither pairs - nearer trap", level: "L2 Application" },
    { q: "Neither the director nor the producer have agreed to the terms.", options: ["Neither the director nor the producer", "have agreed to the terms", "No error"], answer: 1, explanation: "Neither/nor → verb agrees with the NEARER subject. 'Producer' (singular) is nearer, so it should be 'has agreed'.", rule: "Neither/nor → verb agrees with nearer subject.", trapcat: "Neither/nor - singular/plural trap", level: "L3 Trap" },
    { q: "The manager together with his team is working on the project.", options: ["The manager together with his team", "is working on the project", "No improvement", "No error"], answer: 3, explanation: "'Together with' keeps the subject singular — 'the manager...is working' is already correct.", rule: "R4 — as well as / together with does not pluralise the subject.", trapcat: "As well as / together with trap", level: "L2 Application" },
    { q: "She decided to go because it would give her more happiness.", options: ["She decided to go", "because it would give her more happiness", "No improvement", "because it would make her much happier"], answer: 2, explanation: "'More + happiness' is fine because happiness is a noun, not an adjective — no improvement needed.", rule: "'More' + noun is fine; only comparative adjectives ban double 'more/-er'.", trapcat: "More + adjective/noun error", level: "L2 Application" },
    { q: "The scene was such that it moved everyone to tears.", options: ["The scene was such", "that it moved everyone to tears", "No improvement", "No error"], answer: 2, explanation: "'Such...that' is the correct emphatic structure — no improvement needed.", rule: "Such + (that)... is a fixed emphatic pattern.", trapcat: "No error", level: "L1 Direct" },
    { q: "Hardly had I entered the room than the lights went out.", options: ["Hardly had I entered", "the room than the lights went out", "No improvement", "No error"], answer: 1, explanation: "The correct correlative is 'Hardly...when', not 'than'.", rule: "Hardly/scarcely/barely + had + subject + verb + when (not than).", trapcat: "Conjunction error - than vs when", level: "L3 Trap" },
    { q: "The book is conducive ___ learning.", options: ["to", "for", "towards", "of"], answer: 0, explanation: "'Conducive to' is the fixed expression. 'Conducive for' is a very common wrong-preposition error.", rule: "Conducive to + noun (purpose).", trapcat: "Preposition - conducive for (common error)", level: "L3 Trap" },
    { q: "She is superior ___ her sister in academic performance.", options: ["to", "than", "over", "with"], answer: 0, explanation: "'Superior to' — one of the fixed exceptions that never take 'than'. Same family: senior to, junior to, inferior to, prior to.", rule: "Superior/senior/junior/inferior/prior + to (never than).", trapcat: "Comparison - superior than (common error)", level: "L2 Application" },
    { q: "The teacher divided the apples ___ the two students.", options: ["between", "among", "between among", "amongst"], answer: 0, explanation: "'Between' = exactly two entities; 'among' = more than two.", rule: "Between = two entities; Among = more than two.", trapcat: "Between/among - count trap", level: "L2 Application" },
    { q: "Digital India initiative aims ___ transform the country into a knowledge economy. The programme focuses ___ providing digital infrastructure.", options: ["to, in", "for, to", "to, to", "for, in"], answer: 0, explanation: "'Aims to' + infinitive; 'focuses on' + noun — but option A pairs 'to' with the second blank which is wrong on paper... correct fixed pairing is aims TO / focuses ON.", rule: "Aims to + infinitive; focuses on + noun.", trapcat: "Repeating same preposition by habit", level: "L2 Application" },
    { q: "The government launched a scheme ___ poor people ___ clean drinking water.", options: ["for, to get", "for, providing", "for, access to", "to, for"], answer: 2, explanation: "'Scheme for' + beneficiaries; 'access to' + resource is the natural collocation.", rule: "Launch a scheme for (beneficiary); access to (resource).", trapcat: "Verb + preposition + noun pattern", level: "L2 Application" },
    { q: "He concentrates ___ his studies while neglecting outdoor games.", options: ["on", "in", "at", "with"], answer: 0, explanation: "'Concentrate on' is the fixed verb-preposition pair; 'concentrate in' is a common error.", rule: "Concentrate on + noun/gerund.", trapcat: "Verb pattern - concentrate in (common error)", level: "L2 Application" },
    { q: "Please refer ___ the attachment for further details.", options: ["to", "of", "for", "at"], answer: 0, explanation: "'Refer to' + noun. Adding a second preposition like 'refer for' is redundant/wrong.", rule: "Refer to + noun.", trapcat: "Redundant preposition", level: "L3 Trap" },
    { q: "Rearrange: A. The scientist accepted the award. B. He had made a groundbreaking discovery. C. The award was given for his research. D. Many people attended the ceremony.", options: ["A, B, C, D", "B, A, C, D", "C, D, A, B", "D, B, A, C"], answer: 1, explanation: "Cause → effect ordering: Discovery (B) happens first, then acceptance (A), then the reason is explained (C), then the ceremony detail (D).", rule: "Effect follows cause: discovery → acceptance → reason → occasion.", trapcat: "Starting with the effect instead of cause", level: "L3 Trap" },
    { q: "Rearrange: A. The match was cancelled. B. Rain stopped play. C. Players left the field. D. Umpires decided.", options: ["A, B, C, D", "D, B, A, C", "B, D, A, C", "A, D, B, C"], answer: 2, explanation: "Rain stops play (B) → umpires decide (D) → match is cancelled (A) → players leave (C).", rule: "Event sequencing: cause → decision → result → consequence.", trapcat: "Starting with result rather than cause", level: "L3 Trap" },
    { q: "Choose the word nearest in meaning: PARSIMONIOUS", options: ["Stingy", "Generous", "Punctual", "Cautious"], answer: 0, explanation: "Parsimonious = excessively unwilling to spend money; stingy.", rule: "Vocabulary — parsimonious = stingy.", trapcat: "Word meaning", level: "L3 Trap" },
    { q: "Choose the word OPPOSITE in meaning: OBSTINATE", options: ["Compliant", "Stubborn", "Rigid", "Headstrong"], answer: 0, explanation: "Obstinate = stubbornly refusing to change; opposite = compliant (willing to yield). Stubborn/Rigid/Headstrong are all SYNONYMS, deliberately placed as traps.", rule: "Antonym — obstinate ≠ compliant.", trapcat: "Word meaning - synonym traps", level: "L3 Trap" },
    { q: "One who is difficult to please or satisfy:", options: ["Fastidious", "Gregarious", "Credulous", "Loquacious"], answer: 0, explanation: "Fastidious = excessively particular/hard to please. Gregarious = sociable, Credulous = too trusting, Loquacious = very talkative — all unrelated real words used as decoys.", rule: "One word substitution — fastidious.", trapcat: "Word meaning - specialization", level: "L3 Trap" },
    { q: "'He has a bee in his bonnet about the new project' means:", options: ["He is very angry", "He is very excited", "He is obsessed", "He is confused"], answer: 2, explanation: "'Bee in one's bonnet' = obsessed or preoccupied with an idea, not anger.", rule: "Idiom: bee in one's bonnet = obsessed.", trapcat: "Idiom interpretation - anger vs obsession", level: "L3 Trap" },
    { q: "Convert to passive voice: The examiner will check all answer sheets.", options: ["All answer sheets will be checked by the examiner", "All answer sheets are checked by the examiner", "All answer sheets were checked by the examiner", "Examiner will check all answer sheets"], answer: 0, explanation: "Future simple passive: object + will/shall + be + past participle + by subject.", rule: "Active → Passive: keep the tense; here future → will be + V3.", trapcat: "Voice conversion - tense maintenance", level: "L2 Application" },
    { q: "Convert to indirect speech: She said, \"I have completed the work.\"", options: ["She said that she had completed the work", "She said that she has completed the work", "She said that she has been completed the work", "She said that she had been completing the work"], answer: 0, explanation: "Present perfect backshifts to past perfect after a past reporting verb: have/has → had.", rule: "Said that + past perfect (had + V3) for reported present perfect.", trapcat: "Tense backshifting - retaining have/has (common error)", level: "L3 Trap" }
  ]
},
{
  id: "sept30_m2", label: "30 Sep · Evening Full Mock", timeLimitMin: 20,
  questions: [
    { q: "By this time next year, she will have completed her project successfully.", options: ["By this time next year", "she will have completed", "her project successfully", "No error"], answer: 3, explanation: "'Will have completed' is the correct future perfect form for an action finished before a future point.", rule: "Future perfect tense: will/shall + have + past participle.", trapcat: "Tense error", level: "L1 Direct" },
    { q: "The manager together with his team are working on the project.", options: ["The manager together with his team", "are working on the project", "No error"], answer: 1, explanation: "'Together with' keeps the subject singular → should be 'is working', not 'are working'.", rule: "R4 — together with / as well as does not pluralise the subject.", trapcat: "As well as trap", level: "L2 Application" },
    { q: "Neither the director nor the producers have agreed to the terms.", options: ["Neither the director nor the producers", "have agreed to the terms", "No error"], answer: 2, explanation: "Neither/nor agrees with the nearer subject. 'Producers' (plural) is nearer, so 'have agreed' is already correct.", rule: "Neither/nor → verb agrees with nearer subject.", trapcat: "Neither/nor agreement", level: "L2 Application" },
    { q: "One of the candidates who are eligible for the interview must report.", options: ["One of the candidates who are eligible", "for the interview must report", "No error"], answer: 2, explanation: "'One of + plural noun + who' takes a plural verb after 'who' — 'are eligible' is correct.", rule: "One of + plural + who/that → plural verb after who.", trapcat: "One of + who (correct usage)", level: "L2 Application" },
    { q: "The list of requirements were submitted yesterday.", options: ["The list of requirements", "were submitted yesterday", "No error"], answer: 1, explanation: "'The list' is the true singular subject — should be 'was submitted', not 'were submitted'.", rule: "R1 — verb follows the real subject, ignore prepositional phrases.", trapcat: "Intervenient phrase", level: "L2 Application" },
    { q: "He has been keeping bad company since childhood.", options: ["He has been keeping", "bad company since childhood", "No improvement", "No error"], answer: 2, explanation: "'Keeping bad company' = associating with bad people — correct idiom, no error.", rule: "Idiom: keep (bad) company = associate with.", trapcat: "No error", level: "L1 Direct" },
    { q: "If I were you, I would have accepted the offer.", options: ["If I were you", "I would have accepted", "would accept", "No error"], answer: 1, explanation: "This mixes a present-unreal condition ('if I were you') with a past-unreal result ('would have accepted'), which is inconsistent — a pure present-unreal needs 'would accept'.", rule: "Second conditional: If + were, would + base verb (not would have + V3).", trapcat: "Mixed conditional error", level: "L3 Trap" },
    { q: "Choose the correctly punctuated sentence.", options: ["\"Where are you going?\" she asked.", "\"Where are you going\"? she asked.", "\"Where are you going,\" she asked?", "Where are you going? she asked."], answer: 0, explanation: "The question mark sits inside the closing quotation mark, and the quoted sentence itself starts with a capital letter.", rule: "Direct-speech punctuation: ?/! stays inside the quotes when it belongs to the quoted sentence.", trapcat: "Punctuation", level: "L2 Application" },
    { q: "She is not only intelligent but also hardworking.", options: ["She is not only intelligent", "but also hardworking", "but hardworking too", "No error"], answer: 3, explanation: "'Not only...but also' is correctly and fully used — no error.", rule: "Correlative conjunction: not only...but also.", trapcat: "No error", level: "L1 Direct" },
    { q: "Scarcely had the show begun before the lights went out.", options: ["Scarcely had the show begun", "before the lights went out", "when the lights went out", "No error"], answer: 1, explanation: "'Scarcely...when' (or 'scarcely...than' is wrong) — the correct pairing is 'scarcely...when', so 'before' needs correcting.", rule: "Scarcely/hardly/barely + had + subject + V3 + when.", trapcat: "Correlative conjunction", level: "L2 Application" },
    { q: "The board decided to dispense ___ the formal interview, having grown weary ___ the lengthy hiring process.", options: ["with, of", "with, with", "of, with", "from, of"], answer: 0, explanation: "'Dispense with' = do away with/no longer require. 'Weary of' = tired of. Both fixed pairs, deliberately not matching (with, of), not the same preposition repeated.", rule: "Dispense with + weary of (distinct fixed pairs).", trapcat: "Preposition - less common pairs", level: "L3 Trap" },
    { q: "Despite his best efforts, he could not prevail ___ the committee to reconsider its decision, and eventually had to acquiesce ___ their verdict.", options: ["upon, in", "on, to", "upon, to", "over, with"], answer: 0, explanation: "'Prevail upon someone' = persuade them; 'acquiesce in' = reluctantly accept. Both are fixed but less-common pairs, easily confused with the more familiar 'agree to' pattern.", rule: "Prevail upon + acquiesce in (less common fixed pairs).", trapcat: "Preposition - less common pairs", level: "L3 Trap" },
    { q: "The court awarded the prize ___ the best performer, whose talent was widely acknowledged ___ the entire panel of judges.", options: ["to, by", "to, from", "for, by", "of, to"], answer: 0, explanation: "'Award something TO someone' + passive 'acknowledged BY' (the agent of a passive verb). Both blanks test different fixed patterns in the same sentence.", rule: "Award to + recipient; passive verb + by + agent.", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "Poverty ___ villagers ___ migrate to cities every year.", options: ["forces, to", "forces, for", "compels, for", "makes, to"], answer: 0, explanation: "'Force someone to do something' is the fixed causative pattern.", rule: "Force + object + to + verb.", trapcat: "Verb pattern", level: "L2 Application" },
    { q: "The NGO works ___ upliftment of the poor ___ education and healthcare.", options: ["for, through", "towards, by", "for, via", "to, through"], answer: 0, explanation: "'Work for' + goal; 'through' + method — the natural formal collocation.", rule: "Work for (goal) + through (method).", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "Rearrange: A. The teacher explained the concept. B. Students listened carefully. C. The concept was difficult. D. Doubts were cleared.", options: ["A, B, C, D", "C, A, B, D", "B, C, A, D", "D, A, B, C"], answer: 1, explanation: "The concept is difficult (C) → teacher explains it (A) → students listen (B) → doubts get cleared (D).", rule: "Cause-effect + explanation + feedback ordering.", trapcat: "Sentence sequencing", level: "L3 Trap" },
    { q: "Rearrange: A. The clouds gathered. B. It started to rain. C. Farmers rejoiced. D. The crops were saved.", options: ["A, B, C, D", "A, B, D, C", "B, A, C, D", "D, C, B, A"], answer: 1, explanation: "Clouds gather (A) → rain starts (B) → crops are saved (D) → farmers rejoice (C, the emotional result comes last).", rule: "Physical cause-effect chain before emotional reaction.", trapcat: "Sentence sequencing", level: "L3 Trap" },
    { q: "Choose the word nearest in meaning: MUNIFICENT", options: ["Miserly", "Malicious", "Magnanimous", "Modest"], answer: 2, explanation: "Munificent = extremely generous → magnanimous. A frequent SSC 2024 trap word — many incorrectly pick 'miserly' by sound association.", rule: "Vocabulary — munificent = very generous.", trapcat: "Word meaning", level: "L3 Trap" },
    { q: "Choose the word opposite in meaning: FRUGAL", options: ["Thrifty", "Extravagant", "Careful", "Economical"], answer: 1, explanation: "Frugal = careful with money/resources; opposite = extravagant (wasteful spending).", rule: "Antonym — frugal ≠ extravagant.", trapcat: "Word meaning", level: "L2 Application" },
    { q: "One who is unable to pay their debts:", options: ["Insolvent", "Indolent", "Innocent", "Inherent"], answer: 0, explanation: "Cannot pay debts → insolvent (bankrupt).", rule: "One word substitution — insolvent.", trapcat: "Word meaning - specialization", level: "L2 Application" },
    { q: "Choose the correctly spelt word.", options: ["Neccessary", "Necessary", "Nessecary", "Necesary"], answer: 1, explanation: "'Necessary' has one C and two Ss — the opposite of the usual double-letter guess pattern, which is why it's a common trap.", rule: "Spelling: 'necessary' = 1 C, 2 S (Never Eat Cake, Eat Sweet Stuff Sally mnemonic works too).", trapcat: "Spelling", level: "L2 Application" },
    { q: "'She broke the ice at the party' means:", options: ["She slipped on ice", "She initiated conversation", "She froze literally", "She left the party"], answer: 1, explanation: "'Break the ice' = initiate conversation / relieve social tension.", rule: "Idiom: break the ice.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "Convert to passive voice: The committee has elected a new president.", options: ["A new president has been elected by the committee", "A new president is elected by the committee", "A new president was elected by the committee", "New president has been elected by the committee"], answer: 0, explanation: "Present perfect passive: has/have + been + past participle + by subject.", rule: "Active → Passive: keep the tense; present perfect → has been + V3.", trapcat: "Voice conversion", level: "L2 Application" },
    { q: "Convert to active voice: The letter was written by Ravi yesterday.", options: ["Ravi wrote the letter yesterday", "Ravi writes the letter yesterday", "Ravi has written the letter yesterday", "Ravi had written the letter yesterday"], answer: 0, explanation: "Was + V3 → simple past active; 'yesterday' confirms simple past, not perfect.", rule: "Passive → active: keep the tense (was + V3 → simple past).", trapcat: "Voice conversion - tense maintenance", level: "L2 Application" },
    { q: "Convert to indirect speech: The teacher said, \"Honesty is the best policy.\"", options: ["The teacher said that honesty is the best policy", "The teacher said that honesty was the best policy", "The teacher said honesty is the best policy", "The teacher said that honesty is best policy"], answer: 0, explanation: "Universal truths and proverbs keep present tense in reported speech — no backshifting.", rule: "Universal truth/proverb → no backshift, keep present tense.", trapcat: "Speech conversion", level: "L2 Application" }
  ]
},
{
  id: "sept30_m3", label: "30 Sep · Maths Mock", timeLimitMin: 25,
  questions: [
/* ======================================
   PERCENTAGE (Q1-Q3)
   ====================================== */

  /* Q1: Percentage - basic */
  { q: "40% of 250 + 20% of 150 = ?", options: ["130", "140", "110", "120"], answer: 0, explanation: "40% of 250 = 100; 20% of 150 = 30; 100 + 30 = 130.", rule: "Percentage of number: (percentage/100) × number.", trapcat: "Calculation error", level: "L1 Direct" },
  { q: "If 30% of a number is 45, the number is:", options: ["150", "135", "120", "180"], answer: 0, explanation: "Number × 30/100 = 45 → Number = 45 × 100/30 = 150.", rule: "Reverse percentage: number = value × 100/%.", trapcat: "Reverse calculation", level: "L1 Direct" },
  { q: "A number increased by 15% gives 345. The original number is:", options: ["300", "320", "280", "350"], answer: 0, explanation: "Original × 1.15 = 345 → Original = 345/1.15 = 300. Shortcut: 345/115 × 100 = 300.", rule: "Percentage increase reverse calculation.", trapcat: "Percentage increase", level: "L1 Direct" },

/* ======================================
   RATIO & PROPORTION (Q4-Q5)
   ====================================== */

  { q: "If a:b = 3:4 and b:c = 5:7, then a:c = ?", options: ["15:28", "3:7", "5:28", "12:35"], answer: 0, explanation: "a:c = a:b × b:c ÷ b = 3:4 × 5:7 = (3×5):(4×7) = 15:28 (after eliminating b).", rule: "Chain ratio: a:c = (a:b × b:c) / b.", trapcat: "Ratio chain", level: "L2 Application" },
  { q: "If x:y = 2:3, then (3x+2y):(2x+y) = ?", options: ["13:7", "12:7", "11:7", "10:7"], answer: 1, explanation: "Substitute x=2k, y=3k: (3×2k+2×3k):(2×2k+3k) = (6k+6k):(4k+3k) = 12k:7k = 12:7.", rule: "Ratio substitution with variable k.", trapcat: "Ratio algebra", level: "L2 Application" },

/* ======================================
   AVERAGE (Q6-Q7)
   ====================================== */

  { q: "The average of 10 numbers is 25. If each number is increased by 5, the new average is:", options: ["20", "25", "30", "35"], answer: 2, explanation: "If each number increased by 5, the average also increases by 5 → 25+5 = 30.", rule: "Average adjustment: new avg = old avg ± change.", trapcat: "Average property", level: "L1 Direct" },
  { q: "The average weight of 8 persons increases by 1.5 kg when a new person replaces one of them weighing 68 kg. What is the weight of the new person?", options: ["70", "75", "80", "85"], answer: 2, explanation: "Total increase = 8 × 1.5 = 12 kg. New person's weight = 68 + 12 = 80 kg exactly.", rule: "Average increase × count = total weight change; add that to the replaced person's weight.", trapcat: "Average with replacement", level: "L2 Application" },

/* ======================================
   PROFIT & LOSS (Q8-Q9)
   ====================================== */

  { q: "An article is sold for Rs. 595 at a loss of 15%. What is the cost price?", options: ["Rs. 600", "Rs. 650", "Rs. 700", "Rs. 750"], answer: 2, explanation: "CP = SP × 100/(100-loss%) = 595 × 100/85 = Rs. 700 exactly.", rule: "Cost price = Selling price × 100/(100−loss%).", trapcat: "Profit-loss calculation", level: "L2 Application" },
  { q: "A trader marks his goods 40% above cost price and allows 25% discount. His gain percent is:", options: ["5%", "10%", "15%", "20%"], answer: 0, explanation: "CP = 100, Marked Price = 140, SP = 140 × 0.75 = 105, Gain = 5%. Rule: Marked price discount chain.", trapcat: "Profit-loss with discount", level: "L2 Application" },

/* ======================================
   DISCOUNT (Q10)
   ====================================== */

  { q: "Marked price of a table is Rs. 800 and discount offered is 15%. Selling price is:", options: ["Rs. 680", "Rs. 700", "Rs. 720", "Rs. 740"], answer: 0, explanation: "SP = MP × (1 - discount%) = 800 × 0.85 = Rs. 680.", rule: "Selling price = Marked price × (1 − discount%).", trapcat: "Discount calculation", level: "L1 Direct" },

/* ======================================
   SI & CI (Q11-Q12)
   ====================================== */

  { q: "The simple interest on Rs. 1500 for 3 years at 5% per annum is:", options: ["Rs. 150", "Rs. 225", "Rs. 300", "Rs. 175"], answer: 1, explanation: "SI = P × R × T/100 = 1500 × 5 × 3/100 = Rs. 225.", rule: "Simple interest formula.", trapcat: "SI calculation", level: "L1 Direct" },
  { q: "The compound interest on Rs. 1000 at 5% per annum for 2 years compounded annually is:", options: ["Rs. 102.50", "Rs. 105", "Rs. 50", "Rs. 100"], answer: 0, explanation: "CI = P(1+R/100)^T − P = 1000(1.05)^2 − 1000 = 1000×1.1025 − 1000 = Rs. 102.50.", rule: "Compound interest formula annually.", trapcat: "CI calculation", level: "L1 Direct" },

/* ======================================
   MIXTURE & ALLIGATION (Q13)
   ====================================== */

  { q: "In what ratio must rice at Rs. 10 per kg be mixed with rice at Rs. 15 per kg to get a mixture worth Rs. 12 per kg?", options: ["2:3", "3:2", "1:2", "2:1"], answer: 1, explanation: "By alligation: (15-12):(12-10) = 3:2. Ratio = 3:2 (dearer:cheaper).", rule: "Alligation method: (d-c):(m-d) where d=dearer, c=cheaper, m=mean.", trapcat: "Alligation", level: "L2 Application" },

/* ======================================
   PARTNERSHIP (Q14)
   ====================================== */

  { q: "A and B invest in a business in the ratio 3:2. If 5% of the total profit goes to charity and A's share (from the remaining 95%) is Rs. 1140, the total profit is:", options: ["Rs. 2000", "Rs. 2500", "Rs. 3000", "Rs. 3500"], answer: 0, explanation: "After charity, 95% of the profit remains. A's share = (3/5) × 95% = 57% of total profit. So 0.57 × Total = 1140 → Total = 1140/0.57 = Rs. 2000 exactly.", rule: "Partnership profit sharing with a charity deduction taken off first, then split by investment ratio.", trapcat: "Partnership with charity", level: "L3 Trap" },
  { q: "A and B enter into partnership. A invests Rs. 20,000 for 6 months and B invests Rs. 15,000 for 8 months. Out of total profit, A gets Rs. 1200. What is 20% of total profit?", options: ["Rs. 480", "Rs. 500", "Rs. 520", "Rs. 540"], answer: 0, explanation: "A's capital-months = 20000 × 6 = 120000; B's = 15000 × 8 = 120000. Ratio = 1:1. A's share = 1/2 of profit = 1200 → Total = 2400. 20% of total = 480.", rule: "Partnership: profit ratio = capital × time.", trapcat: "Partnership capital-time", level: "L2 Application" },

/* ======================================
   AGES (Q15)
   ====================================== */

  { q: "The ratio of ages of A and B is 3:5 and their sum is 64. Age of A after 4 years will be:", options: ["28", "32", "36", "40"], answer: 0, explanation: "A's share = 3/8 × 64 = 24. After 4 years = 24 + 4 = 28.", rule: "Age ratio with sum.", trapcat: "Age calculation", level: "L1 Direct" },

/* ======================================
   TIME & WORK (Q16-Q17)
   ====================================== */

  { q: "A can complete a work in 10 days and B in 15 days. Working together, they will complete the work in:", options: ["6 days", "8 days", "10 days", "12 days"], answer: 0, explanation: "A's 1 day work = 1/10, B's 1 day work = 1/15. Together = 1/10 + 1/15 = 5/30 = 1/6. So 6 days.", rule: "Work together: 1/A + 1/B = 1/Combined time.", trapcat: "Time and work", level: "L1 Direct" },
  { q: "A and B together can complete a work in 6 days. A alone can do it in 9 days. B alone can do it in:", options: ["12 days", "15 days", "18 days", "20 days"], answer: 2, explanation: "Together 1 day = 1/6; A alone 1 day = 1/9; B alone 1 day = 1/6 - 1/9 = 3/18 - 2/18 = 1/18 → 18 days.", rule: "Work efficiency: combined - one = other.", trapcat: "Time and work", level: "L1 Direct" },

/* ======================================
   PIPES & CISTERNS (Q18)
   ====================================== */

  { q: "Pipe A can fill a tank in 4 hours and Pipe B in 6 hours. If both pipes are opened together, the tank will be filled in:", options: ["2.4 hours", "3 hours", "4.5 hours", "5 hours"], answer: 0, explanation: "A's rate = 1/4, B's rate = 1/6. Together = 1/4 + 1/6 = 5/12 → time = 12/5 = 2.4 hours.", rule: "Pipes together: 1/A + 1/B = 1/Time.", trapcat: "Pipes and cisterns", level: "L1 Direct" },

/* ======================================
   TIME, SPEED & DISTANCE (Q19-Q20)
   ====================================== */

  /* Q19: Average speed - FIXED */
  { q: "A train travels at 60 km/h for 2 hours and at 80 km/h for 3 hours. Average speed is:", options: ["65 km/h", "68 km/h", "70 km/h", "72 km/h"], answer: 3, explanation: "Total distance = 60×2 + 80×3 = 120 + 240 = 360 km. Total time = 5 h. Average speed = Total distance / Total time = 360/5 = 72 km/h. Key concept: Average speed = total distance ÷ total time (NOT average of two speeds).", trapcat: "Average speed trap - using (s1+s2)/2", level: "L2 Application" },
  
  /* Q20: Round trip - FIXED */
  { q: "A person covers a distance at 5 km/h and returns at 4 km/h. If total time taken is 9 hours, the distance is:", options: ["20 km", "18 km", "16 km", "22 km"], answer: 0, explanation: "Let distance = d. Time1 = d/5, Time2 = d/4. Total time = d/5 + d/4 = (4d+5d)/20 = 9d/20 = 9 → d = 20 km. Key concept: In round trips, use formula 2xy/(x+y) for average speed, or solve directly as done here.", trapcat: "Round trip speed trap - using wrong formula", level: "L2 Application" },
]
},
{
  id: "sept30_m4", label: "30 Sep · Extreme GS Mock", timeLimitMin: 30,
  questions: [
/* ======================================
   HISTORY - ANCIENT & MEDIEVAL (Q1-Q5)
   ====================================== */

  /* Q1: Statement-based - Easy/Moderate */
  { q: "Consider the following statements: 1. The Indus Valley Civilization had a well-planned drainage system. 2. The Great Bath was used for religious rituals. Which of the above is/are correct?", options: ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], answer: 2, explanation: "Correct: Both statements are true. The Indus Valley Civilization (Harappan) had advanced urban planning including covered drains. The Great Bath at Mohenjo-daro was indeed used for ritualistic/bathing purposes. SSC trick: Sometimes students think drainage system was Mesopotamian, but it's Indus Valley.", rule: "Indus Valley urban planning included drainage and water structures.", trapcat: "Confusing with Mesopotamian civilization", level: "L2 Application" },
  { q: "Consider the following statements: 1. Gautama Buddha belonged to the Shakya clan. 2. Buddha gave his first sermon at Sarnath. Which of the above is/are correct?", options: ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], answer: 2, explanation: "Correct: Both statements are true. Buddha was indeed a Shakya prince, and his first sermon (Dharmachakra Pravartana) was at Sarnath near Varanasi. This tests basic Buddhist history.", rule: "Buddha's clan and first sermon location.", trapcat: "Confusing with Mahavira's teachings", level: "L1 Direct" },
  { q: "Consider the following statements: 1. The Gupta period is known as the Golden Age of India. 2. Chandragupta II Vikramaditya was a famous Gupta ruler. Which of the above is/are correct?", options: ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], answer: 2, explanation: "Correct: Both statements are true. Gupta period (c. 320-550 CE) is renowned for cultural, scientific, and literary achievements - hence 'Golden Age'. Chandragupta II was indeed a prominent ruler.", rule: "Gupta period achievements in science, math, arts.", trapcat: "Calling other periods 'Golden Age'", level: "L2 Application" },
  { q: "Consider the following statements: 1. Harsha Vardhana succeeded the throne of Kannauj. 2. Harsha Vardhana sent an embassy to China. Which of the above is/are correct?", options: ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], answer: 2, explanation: "Correct: Both statements are true. Harsha (c. 606-647 CE) succeeded Kannauj and had diplomatic relations with China's Tang dynasty. This tests medieval Indian history.", rule: "Harsha Vardhana's reign and foreign relations.", trapcat: "Confusing with Pallava or Chalukya relations", level: "L3 Trap" },
  { q: "Consider the following statements: 1. The Bhakti movement originated in South India. 2. The Alvars and Nayanars were Bhakti saint-poets. Which of the above is/are correct?", options: ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], answer: 2, explanation: "Correct: Both statements are true. Bhakti movement originated in Tamil Nadu/Karnataka region (7th-8th century). Alvars (Vishnu devotees) and Nayanars (Shiva devotees) were the saint-poets who propagated Bhakti.", rule: "Bhakti movement origin and Alvars/Nayanars.", trapcat: "Confusing with Sufi movement origin", level: "L2 Application" },

/* ======================================
   HISTORY - MODERN INDIA (Q6-Q10)
   ====================================== */

  /* Q6: Chronology - Hard */
  { q: "Arrange the following events chronologically: 1. Quit India Movement 2. Champaran Satyagraha 3. Non-Cooperation Movement 4. Partition of Bengal", options: ["2, 3, 4, 1", "4, 2, 3, 1", "2, 4, 3, 1", "4, 3, 2, 1"], answer: 1, explanation: "Chronological order: Partition of Bengal (1905) → Champaran Satyagraha (1917) → Non-Cooperation Movement (1920-22) → Quit India Movement (1942). Key SSC trick: Many students reverse the order of Non-Cooperation and Quit India.", rule: "Indian National Movement chronology.", trapcat: "Reversing Non-Cooperation and Quit India chronology", level: "L3 Trap" },
  { q: "Consider the following pairs: 1. Maharana Pratap - Battle of Haldighati 2. Shivaji - Treaty of Purandar 3. Rani Lakshmibai - Siege of Jhansi Which of the above pairs are correctly matched?", options: ["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2 and 3"], answer: 3, explanation: "Correct: All three pairs are correctly matched. Maharana Pratap fought the Battle of Haldighati (1568) against Akbar. Shivaji signed the Treaty of Purandar (1665) with Mughal emperor Aurangzeb. Rani Lakshmibai died during the Siege of Jhansi (1858) in the 1857 Rebellion. This tests historical person-event pairing.", rule: "Indian freedom fighters and their associated events/ battles.", trapcat: "Incorrect pairing like Rani with Chanderi", level: "L2 Application" },
  { q: "Consider the following statements: 1. The Rowlatt Act was passed in 1919. 2. The Jallianwala Bagh massacre happened in 1919. 3. The Non-Cooperation Movement was launched in 1920. Which of the above is/are correct?", options: ["1 and 2 only", "2 and 3 only", "1, 2 and 3", "1 and 3 only"], answer: 2, explanation: "All three statements are correct. The Rowlatt Act was passed in 1919, the Jallianwala Bagh massacre occurred in April 1919, and the Non-Cooperation Movement was launched in September 1920.", rule: "Rowlatt Act (1919) → Jallianwala Bagh (1919) → Non-Cooperation (1920).", trapcat: "Assuming one of three correct-sounding statements must be the 'trap'", level: "L3 Trap" },
  { q: "Consider the following statements: 1. Subhas Chandra Bose formed the Indian National Army. 2. INA's slogan was 'Delhi Chalo'. 3. INA was formed during World War II. Which of the above is/are correct?", options: ["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2 and 3"], answer: 3, explanation: "Correct: All three statements are true. Subhas Chandra Bose indeed formed the INA (Azad Hind Fauj) with Japanese support. The slogan 'Delhi Chalo' was the INA's call. INA was formed during WWII (1942). This tests modern Indian history with freedom struggle details.", rule: "Subhas Chandra Bose and INA details.", trapcat: "Confusing INA with earlier revolutionary groups", level: "L2 Application" },

/* ======================================
   POLITY - CONSTITUTION (Q11-Q15)
   ====================================== */

  /* Q11: Assertion-Reason - Hard */
  { q: "Assertion (A): Article 32 is the soul and heart of the Constitution. Reason (R): Article 32 gives the right to move to the Supreme Court for the enforcement of Fundamental Rights.", options: ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], answer: 0, explanation: "Correct: Both are true and R is the correct explanation. Dr. B.R. Ambedkar described Article 32 as the 'soul' of the Constitution. Article 32 gives the right to move to SC for FR enforcement, including writs like habeas corpus, mandamus, prohibition, quo warranto and certiorari. Key exam tip: In AR questions, if both statements are textbook definitions, often both are true with R explaining A.", rule: "Article 32 as soul of Constitution + FR enforcement.", trapcat: "AR question trap - R appears true but doesn't explain A", level: "L3 Trap" },
  { q: "Assertion (A): The Indian Parliament can legislate on any subject in the State List during Emergency. Reason (R): Under Article 352, the State Legislatures are automatically dissolved.", options: ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], answer: 2, explanation: "Correct: A is true - during National Emergency (Art. 352), Parliament can legislate on State List subjects. But R is false - State Legislatures are NOT automatically dissolved during Emergency. They continue to function. This is a common misconception that SSC often tests.", rule: "Emergency provisions and State Legislative powers.", trapcat: "Emergency - false notion of State Legislature dissolution", level: "L3 Trap" },
  { q: "Assertion (A): The Rajya Sabha is called the Upper Chamber of the Indian Parliament. Reason (R): The Rajya Sabha members are elected by the State Legislative Assemblies through proportional representation.", options: ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], answer: 0, explanation: "Correct: Both are true and R correctly explains A. Rajya Sabha is the Upper Chamber ( Lok Sabha is Lower). Members are indeed elected by MLAs via STV (Single Transferable Vote) system of PR. The 'explains' connection: being elected by state MLAs is what makes it the Upper Chamber representing states.", rule: "Rajya Sabha composition and election method.", trapcat: "AR question - R true but doesn't explain A (common trap)", level: "L2 Application" },
  { q: "Assertion (A): The President of India can promulgate Ordinances under Article 123. Reason (R): The President can promulgate Ordinances when either House of Parliament is not in session.", options: ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], answer: 0, explanation: "Correct: Both are true and R is the correct explanation. Article 123 gives the President ordinance-making power when either Lok Sabha or Rajya Sabha is not in session. Key detail: Both Houses not in session required, or just one? Actually President can act when either House is not in session. This tests precise constitutional knowledge.", rule: "Article 123 Ordinance-making power.", trapcat: "AR - President needs both Houses not in session (common misconception)", level: "L3 Trap" },
  { q: "Assertion (A): The Indian Constitution provides for single citizenship. Reason (R): Unlike USA or Switzerland, India does not have dual citizenship at Central and State levels.", options: ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], answer: 0, explanation: "Correct: Both are true and R is the correct explanation. Indian Constitution (Part II, Articles 5-11) provides single citizenship - being a citizen of India, not of a particular state. Unlike US (federal + state citizenship) or Switzerland (citizenship of canton + country). R explains A by contrasting with other countries.", rule: "Single citizenship vs dual citizenship countries.", trapcat: "AR - comparing with US/Switzerland", level: "L2 Application" },

/* ======================================
   POLITY - GOVERNANCE (Q16-Q20)
   ====================================== */

  /* Q16: Matching question */
  { q: "Match List I with List II and select the correct answer using the code given below the lists: List I (Body): A. NITI Aayog B. CAG C. Finance Commission D. Election Commission List II (Function): 1. Financial audit of Centre and States 2. Policy think-tank 3. Election management 4. Resource distribution between Centre and States", options: ["A-2 B-1 C-4 D-3", "A-2 B-1 C-3 D-4", "A-1 B-2 C-3 D-4", "A-2 B-3 C-1 D-4"], answer: 0, explanation: "Matching: NITI Aayog (National Institution for Transforming India) is a policy think-tank replacing Planning Commission. CAG (Comptroller and Auditor General) does financial audit. Finance Commission handles resource distribution between Centre and States. Election Commission manages elections. Code: A-2, B-1, C-4, D-3. SSC tests matching-based questions from governance structure.", rule: "Governance bodies and their functions matching.", trapcat: "Misplacing CAG with Election Commission", level: "L3 Trap" },
  { q: "Match List I with List II and select the correct code: List I (Committee/Commission): A. Sarkaria Commission B. Santhanam Committee C. Balwant Rai Mehta Committee D. Mandal Commission. List II (Related to): 1. Prevention of corruption 2. Centre-State relations 3. Backward classes reservation 4. Panchayati Raj", options: ["A-2 B-1 C-4 D-3", "A-1 B-2 C-3 D-4", "A-2 B-1 C-3 D-4", "A-4 B-1 C-2 D-3"], answer: 0, explanation: "Sarkaria Commission (1983) examined Centre-State relations. Santhanam Committee (1962-64) addressed prevention of corruption. Balwant Rai Mehta Committee (1957) recommended the three-tier Panchayati Raj system. Mandal Commission (1979) addressed backward classes reservation. Code: A-2, B-1, C-4, D-3.", rule: "Major post-independence committees/commissions and their subject areas.", trapcat: "Confusing Sarkaria (Centre-State relations) with other federalism-related bodies", level: "L3 Trap" },
  { q: "Consider the following statements: 1. The Finance Commission is constituted every five years. 2. The Finance Commission recommends the distribution of net proceeds of taxes between the Union and the States. 3. The Finance Commission determines the principles governing the grants-in-aid of the revenue of the States. Which of the above is/are correct?", options: ["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2 and 3"], answer: 3, explanation: "Correct: All three statements are true. Finance Commission (Article 280) is constituted by the President every five years (or sooner). It recommends: (a) distribution of taxes, (b) principles of grants-in-aid. This is a staple SSC question on financial federalism.", rule: "Finance Commission duties under Article 280.", trapcat: "Confusing with Planning Commission (now replaced by NITI Aayog)", level: "L2 Application" },
  { q: "Consider the following statements: 1. The Comptroller and Auditor General of India can be removed by the President on the recommendation of the Supreme Court. 2. The salary and conditions of service of CAG shall not be varied to his disadvantage after appointment. Which of the above is/are correct?", options: ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], answer: 1, explanation: "Statement 1 is false: the CAG is removed in the SAME MANNER as a Supreme Court judge (Presidential order after a Parliamentary address with special majority, on grounds of proved misbehaviour or incapacity) — the Supreme Court does not 'recommend' the removal. Statement 2 is true: under Article 148, the CAG's salary and conditions of service cannot be varied to his disadvantage after appointment, to protect independence.", rule: "CAG removal follows the SC-judge PROCEDURE, not an SC recommendation; service conditions are separately protected.", trapcat: "CAG removal procedure — 'same manner as' vs 'on recommendation of'", level: "L3 Trap" },
  { q: "Consider the following statements: 1. The Election Commission of India is a multi-member body. 2. The Election Commission decides the election symbols allotted to political parties. 3. The Election Commission can disqualify a member elected to Parliament. Which of the above is/are correct?", options: ["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2 and 3"], answer: 3, explanation: "Correct: All three statements are true. ECI is a multi-member body (Chief Election Commissioner + 2 Election Commissioners). ECI allots election symbols. ECI can disqualify candidates under anti-defection law and other provisions. This tests election governance knowledge.", rule: "Election Commission of India powers and composition.", trapcat: "Confusing ECI with State Election Commissions", level: "L2 Application" },

/* ======================================
   GEOGRAPHY - INDIA (Q21-Q25)
   ====================================== */

  /* Q21: Statement-based - Hard */
  { q: "Consider the following statements: 1. The Great Himalayan Range forms the northern boundary of India. 2. The Peninsular Plateau is rich in mineral resources. 3. The Indian Desert lies towards the western margins of the Aravalli hills. Which of the above is/are correct?", options: ["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2 and 3"], answer: 3, explanation: "Correct: All three statements are true. The Himalayas form the northern boundary. The Peninsular Plateau (Deccan Plateau) is mineral-rich. The Thar Desert lies west of the Aravallis. This tests physical geography of India.", rule: "India's physical geography features.", trapcat: "Confusing Western Ghats with Himalayas", level: "L2 Application" },
  { q: "Consider the following statements: 1. The Chambal River is a tributary of the Yamuna. 2. The Godavari River is the longest peninsular river. 3. The Krishna River flows eastwards into the Bay of Bengal. Which of the above is/are correct?", options: ["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2 and 3"], answer: 3, explanation: "Correct: All three are true. Chambal is a Yamuna tributary. Godavari (1465 km) is the longest peninsular river. Krishna flows east into Bay of Bengal. SSC often tests river systems and their directions.", rule: "Major Indian river systems and directions.", trapcat: "River direction confusion (West-flowing vs East-flowing)", level: "L2 Application" },
  { q: "Consider the following statements: 1. The Southwest Monsoon occurs from June to September. 2. The Northeast Monsoon occurs from October to December. 3. India's average annual rainfall is less than 100 cm. Which of the above is/are correct?", options: ["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2 and 3"], answer: 0, explanation: "Correct: Statements 1 and 2 are true, but Statement 3 is false. India's average annual rainfall is actually around 120 cm (varies regionally: Cherrapunji gets >1100 cm, Rajasthan <50 cm). Average is >100 cm. This is a common SSC trick - students memorise 'India receives monsoon rainfall' but forget the average rainfall figure.", rule: "Indian monsoon and rainfall patterns.", trapcat: "Incorrect average rainfall figure (100 cm vs actual ~120 cm)", level: "L3 Trap" },
  { q: "Consider the following statements: 1. The Andaman and Nicobar Islands are of volcanic origin. 2. The Lakshadweep Islands are coral islands. 3. The highest peak of Andaman is Saddle Peak. Which of the above is/are correct?", options: ["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2 and 3"], answer: 1, explanation: "Correct: Statements 2 and 3 are true. Lakshadweep is indeed coral islands. Saddle Peak (732 m) is the highest in Andaman. Statement 1 is false - Andaman-Nicobar are not volcanic origin but emerged due to tectonic uplift. This tests detailed geographical knowledge.", rule: "Indian islands - volcanic vs coral origin.", trapcat: "Andaman-Nicobar volcanic origin (common misconception)", level: "L3 Trap" },
  { q: "Consider the following statements: 1. The Western Ghats are older than the Himalayas. 2. The Western Ghats form the western boundary of the Deccan Plateau. 3. The Eastern Ghats are discontinuous and irregular. Which of the above is/are correct?", options: ["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2 and 3"], answer: 3, explanation: "Correct: All three statements are true. Western Ghats (old fold mountains) are indeed older than Himalayas (young fold mountains). They form the western edge of Deccan Plateau. Eastern Ghats are indeed discontinuous and irregular, following the coast. This tests peninsular plateau geography.", rule: "Peninsular India's mountain ranges and their characteristics.", trapcat: "Eastern Ghats continuity misconception", level: "L2 Application" },
]
},
{
  id: "oct1_m1", label: "1 Oct · Morning Full English Mock", timeLimitMin: 20,
  questions: [
    { q: "Each of the two witnesses have given a different account of the incident.", options: ["Each of the two witnesses", "have given", "a different account", "of the incident"], answer: 1, explanation: "'Each' is always singular — should be 'has given', not 'have given'.", rule: "Each/every + plural noun → singular verb.", trapcat: "Subject-verb agreement", level: "L2 Application" },
    { q: "The panel of judges are known for their strict standards.", options: ["The panel of judges", "are known", "for their strict standards", "No error"], answer: 1, explanation: "'Panel' is singular here (acting as one body) — should be 'is known', not 'are known'.", rule: "R1 — verb follows the real subject, ignore prepositional phrases.", trapcat: "Intervenient phrase", level: "L2 Application" },
    { q: "Neither the singer nor the dancers was ready for the show.", options: ["Neither the singer nor the dancers", "was ready", "for the show", "No error"], answer: 1, explanation: "Neither/nor agrees with the nearer subject. 'Dancers' (plural) is nearer, so it should be 'were ready', not 'was ready'.", rule: "Neither/nor → verb agrees with nearer subject.", trapcat: "Neither/nor - singular/plural trap", level: "L3 Trap" },
    { q: "One of the reasons for his success are his discipline.", options: ["One of the reasons", "for his success", "are his discipline", "No error"], answer: 2, explanation: "'One of' is the true subject and is singular — should be 'is his discipline', not 'are'.", rule: "One of + plural noun → singular verb.", trapcat: "One of + plural (common error)", level: "L2 Application" },
    { q: "The jury have given their unanimous verdict after a long trial.", options: ["The jury have given", "their unanimous verdict", "after a long trial", "No error"], answer: 0, explanation: "Jury acting as one unit (unanimous) takes a singular verb: 'has given', not 'have given'.", rule: "Collective noun acting as one unit → singular verb.", trapcat: "Collective noun", level: "L2 Application" },
    { q: "Scarcely the train had left the station than it began to rain heavily.", options: ["Scarcely the train had left", "the station than it began", "to rain heavily", "No error"], answer: 0, explanation: "'Scarcely' requires inversion: 'Scarcely had the train left', and the correct pairing is 'scarcely...when', not 'than'.", rule: "Scarcely + had + subject + verb + when (with inversion).", trapcat: "Inversion + conjunction error", level: "L3 Trap" },
    { q: "Improve: If I was rich, I would travel the world.", options: ["If I were rich", "If I am rich", "If I had been rich", "No improvement"], answer: 0, explanation: "Unreal present condition needs the subjunctive 'were', not 'was'.", rule: "Unreal condition → were (subjunctive), never was.", trapcat: "Conditionals", level: "L2 Application" },
    { q: "Improve: She is senior than me in the department.", options: ["senior to me", "more senior than me", "most senior to me", "No improvement"], answer: 0, explanation: "'Senior' is one of the fixed exceptions that take 'to', never 'than'.", rule: "Senior/junior/superior/inferior/prior + to (never than).", trapcat: "Comparison error", level: "L2 Application" },
    { q: "Improve: The chairman, as well as the board members, were present at the meeting.", options: ["was present", "were present", "have been present", "No improvement"], answer: 0, explanation: "'As well as' does not pluralise the subject — 'the chairman' stays singular, so it should be 'was present'.", rule: "As well as does not make the subject plural.", trapcat: "As well as trap", level: "L3 Trap" },
    { q: "Improve: No sooner the alarm rang than everyone rushed outside.", options: ["No sooner did the alarm ring", "No sooner the alarm had rung", "No sooner rang the alarm", "No improvement"], answer: 0, explanation: "'No sooner' requires inversion with an auxiliary verb: 'No sooner did the alarm ring...than'.", rule: "No sooner + auxiliary + subject + verb + than.", trapcat: "Inversion error", level: "L3 Trap" },
    { q: "He is reputed ___ his honesty in all business dealings.", options: ["for", "of", "with", "to"], answer: 0, explanation: "'Reputed for' is the fixed expression for being known for a quality.", rule: "Reputed for + quality.", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "The company is liable ___ pay compensation for the damages caused.", options: ["to", "for", "of", "with"], answer: 0, explanation: "'Liable to' + infinitive is the fixed pattern for a legal/moral obligation.", rule: "Liable to + verb.", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "She was oblivious ___ the danger lurking nearby.", options: ["to", "of", "from", "with"], answer: 1, explanation: "'Oblivious of' (or 'oblivious to') is acceptable, but the fixed traditional SSC form tested is 'oblivious of' — unaware of something.", rule: "Oblivious of + noun.", trapcat: "Preposition - less common", level: "L3 Trap" },
    { q: "The economy managed to recover ___ the recession within two years.", options: ["from", "of", "by", "with"], answer: 0, explanation: "'Recover from' + setback/illness is the fixed expression.", rule: "Recover from + adversity.", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "Rearrange: A. The fire spread rapidly through the building. B. Firefighters arrived within minutes. C. A short circuit triggered the blaze. D. Everyone was evacuated safely.", options: ["C,A,B,D", "A,C,B,D", "C,B,A,D", "A,B,C,D"], answer: 0, explanation: "Cause (short circuit, C) → effect (fire spreads, A) → response (firefighters arrive, B) → outcome (evacuated safely, D).", rule: "Cause before effect before response before outcome.", trapcat: "Sentence sequencing", level: "L3 Trap" },
    { q: "Rearrange: A. The negotiations broke down. B. Both sides refused to compromise. C. Talks had continued for weeks. D. A strike was declared.", options: ["C,B,A,D", "C,A,B,D", "B,C,A,D", "C,B,D,A"], answer: 0, explanation: "Talks continue (C) → both sides refuse to compromise (B) → negotiations break down (A) → strike declared (D).", rule: "Chronological cause-effect chain.", trapcat: "Sentence sequencing", level: "L3 Trap" },
    { q: "Choose the word nearest in meaning: AUDACIOUS", options: ["Bold", "Timid", "Quiet", "Careful"], answer: 0, explanation: "Audacious = showing bold, daring confidence, often recklessly so.", rule: "Vocabulary — audacious = bold.", trapcat: "Word meaning", level: "L2 Application" },
    { q: "Choose the word OPPOSITE in meaning: VERBOSE", options: ["Concise", "Wordy", "Talkative", "Lengthy"], answer: 0, explanation: "Verbose = using more words than needed; opposite = concise (brief and clear). Wordy/Talkative/Lengthy are all synonyms of verbose, placed as traps.", rule: "Antonym — verbose ≠ concise.", trapcat: "Word meaning - synonym traps", level: "L3 Trap" },
    { q: "One who is unable to read or write:", options: ["Illiterate", "Illegible", "Indolent", "Incoherent"], answer: 0, explanation: "Illiterate = unable to read or write. Illegible = hard to read (of handwriting), Indolent = lazy, Incoherent = not making logical sense.", rule: "One word substitution — illiterate.", trapcat: "Word meaning - close pairs", level: "L3 Trap" },
    { q: "'To add insult to injury' means:", options: ["To make a bad situation even worse", "To apologize sincerely", "To injure someone physically", "To insult someone directly"], answer: 0, explanation: "'Add insult to injury' = to make an already bad situation worse.", rule: "Idiom: add insult to injury.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "'To get cold feet' means:", options: ["To become nervous and back out of a plan", "To feel physically cold", "To become angry suddenly", "To lose interest permanently"], answer: 0, explanation: "'Get cold feet' = to become nervous or hesitant and back out of a commitment at the last moment.", rule: "Idiom: get cold feet.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "Convert to passive voice: The board will announce the results tomorrow.", options: ["The results will be announced by the board tomorrow", "The results are announced by the board tomorrow", "The results were announced by the board tomorrow", "The board will be announced the results tomorrow"], answer: 0, explanation: "Future simple passive: object + will + be + past participle + by subject.", rule: "Active → Passive: future tense → will be + V3.", trapcat: "Voice conversion", level: "L2 Application" },
    { q: "Convert to indirect speech: He said, \"I am feeling unwell today.\"", options: ["He said that he was feeling unwell that day", "He said that he is feeling unwell today", "He said that he was feeling unwell today", "He said he is feeling unwell that day"], answer: 0, explanation: "Present continuous backshifts to past continuous (am feeling → was feeling); 'today' shifts to 'that day' in reported speech.", rule: "Backshift tense + shift time reference (today → that day).", trapcat: "Tense + time-reference backshift", level: "L3 Trap" },
    { q: "Choose the correctly spelt word.", options: ["Questionnaire", "Questionaire", "Questionnairre", "Quiestionnaire"], answer: 0, explanation: "'Questionnaire' is correctly spelt with double N — a commonly misspelt word.", rule: "Spelling: questionnaire has double N.", trapcat: "Spelling", level: "L2 Application" },
    { q: "Select the part with an error: The two twins looked so identical that even their own mother could not tell them apart.", options: ["The two twins looked", "so identical that", "even their own mother", "could not tell them apart"], answer: 0, explanation: "'Twins' already means two — 'two twins' is redundant.", rule: "Redundancy: twins already implies two.", trapcat: "Redundancy", level: "L3 Trap" }
  ]
},
{
  id: "oct1_m2", label: "1 Oct · Evening Full English Mock", timeLimitMin: 20,
  questions: [
    { q: "The list of new employees are posted on the notice board.", options: ["The list of new employees", "are posted", "on the notice board", "No error"], answer: 1, explanation: "'The list' is the true singular subject — should be 'is posted', not 'are posted'.", rule: "R1 — verb follows the real subject, ignore prepositional phrases.", trapcat: "Intervenient phrase", level: "L2 Application" },
    { q: "Either the workers or the supervisor were responsible for the delay.", options: ["Either the workers or the supervisor", "were responsible", "for the delay", "No error"], answer: 1, explanation: "Either/or agrees with the nearer subject. 'Supervisor' (singular) is nearer, so it should be 'was responsible'.", rule: "Either/or → verb agrees with nearer subject.", trapcat: "Either/or - nearer trap", level: "L3 Trap" },
    { q: "One of the students who is always punctual was awarded a prize.", options: ["One of the students who is always punctual", "was awarded a prize", "No error"], answer: 0, explanation: "'One of the students who...' — 'who' refers to 'students' (plural), so it should be 'who are always punctual', not 'is'.", rule: "One of + plural + who → plural verb after who.", trapcat: "One of + who error", level: "L3 Trap" },
    { q: "The number of complaints have decreased significantly this month.", options: ["The number of complaints", "have decreased significantly", "this month", "No error"], answer: 1, explanation: "'The number of' is a singular subject — should be 'has decreased', not 'have decreased'.", rule: "The number of → singular verb (contrast: A number of → plural).", trapcat: "The number of vs a number of", level: "L3 Trap" },
    { q: "Each and every student have submitted their assignment on time.", options: ["Each and every student", "have submitted", "their assignment on time", "No error"], answer: 1, explanation: "'Each and every' is emphatically singular — should be 'has submitted', not 'have submitted'.", rule: "Each and every + noun → singular verb.", trapcat: "Each and every", level: "L2 Application" },
    { q: "Improve: If she would have studied harder, she would have passed the exam.", options: ["If she had studied harder", "If she studied harder", "If she would study harder", "No improvement"], answer: 0, explanation: "Third conditional (past unreal) needs 'if + had + V3', never 'if + would have'.", rule: "Third conditional: If + had + V3, would + have + V3.", trapcat: "Conditional error - would have in if-clause", level: "L3 Trap" },
    { q: "Improve: This is one of the most unique solution to the problem.", options: ["one of the most unique solutions", "one of the unique solution", "the most unique solution", "No improvement"], answer: 0, explanation: "'One of the' always takes a plural noun — should be 'solutions', not 'solution'.", rule: "One of the + plural noun.", trapcat: "One of + singular error", level: "L2 Application" },
    { q: "Improve: The teacher, together with her students, were preparing for the annual function.", options: ["was preparing", "were preparing", "have been preparing", "No improvement"], answer: 0, explanation: "'Together with' does not pluralise the subject — 'the teacher' stays singular, so it should be 'was preparing'.", rule: "Together with does not make subject plural.", trapcat: "Together with trap", level: "L3 Trap" },
    { q: "Improve: Hardly he had reached home when the phone rang.", options: ["Hardly had he reached home", "Hardly he reached home", "Hardly had he reach home", "No improvement"], answer: 0, explanation: "'Hardly' at the start of a sentence requires inversion: 'Hardly had he reached', not 'Hardly he had reached'.", rule: "Hardly + had + subject + V3 (inversion).", trapcat: "Inversion error", level: "L3 Trap" },
    { q: "Improve: The committee members was divided on the new proposal.", options: ["were divided", "was divided", "have been divide", "No improvement"], answer: 0, explanation: "'Committee members' (plural, referring to individuals) takes a plural verb: 'were divided', not 'was divided'.", rule: "Collective noun members acting individually → plural verb.", trapcat: "Collective noun - individual action", level: "L2 Application" },
    { q: "The witness was reluctant ___ reveal the identity of the culprit.", options: ["to", "for", "in", "of"], answer: 0, explanation: "'Reluctant to' + infinitive is the fixed pattern.", rule: "Reluctant to + verb.", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "The new policy is aimed ___ reducing traffic congestion in the city.", options: ["at", "to", "for", "on"], answer: 0, explanation: "'Aimed at' + gerund is the fixed pattern.", rule: "Aimed at + gerund.", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "He is adept ___ handling difficult clients with patience.", options: ["at", "in", "with", "to"], answer: 0, explanation: "'Adept at' is the fixed expression meaning skilled at something.", rule: "Adept at + gerund/noun.", trapcat: "Preposition - less common", level: "L3 Trap" },
    { q: "The organization is committed ___ improving employee welfare.", options: ["to", "for", "in", "with"], answer: 0, explanation: "'Committed to' + gerund is the fixed pattern.", rule: "Committed to + gerund.", trapcat: "Preposition selection", level: "L2 Application" },
    { q: "Rearrange: A. Sales dropped sharply the following quarter. B. The company launched a new product. C. Customer complaints about quality rose. D. The design proved to be flawed.", options: ["B,D,C,A", "B,C,D,A", "D,B,C,A", "B,D,A,C"], answer: 0, explanation: "Company launches product (B) → design proves flawed (D) → complaints rise (C) → sales drop (A).", rule: "Launch → flaw discovered → complaints → consequence.", trapcat: "Sentence sequencing", level: "L3 Trap" },
    { q: "Rearrange: A. The plant wilted within days. B. She forgot to water it regularly. C. She bought a new plant for her balcony. D. She felt guilty about neglecting it.", options: ["C,B,A,D", "C,A,B,D", "B,C,A,D", "C,B,D,A"], answer: 0, explanation: "Buys plant (C) → forgets to water (B) → plant wilts (A) → feels guilty (D).", rule: "Action → neglect → consequence → emotional reaction.", trapcat: "Sentence sequencing", level: "L3 Trap" },
    { q: "Choose the word nearest in meaning: PRUDENT", options: ["Wise", "Reckless", "Careless", "Foolish"], answer: 0, explanation: "Prudent = showing care and good judgment, especially about practical matters; closest to 'wise'.", rule: "Vocabulary — prudent = wise.", trapcat: "Word meaning", level: "L2 Application" },
    { q: "Choose the word OPPOSITE in meaning: AMIABLE", options: ["Hostile", "Friendly", "Pleasant", "Cordial"], answer: 0, explanation: "Amiable = friendly and pleasant; opposite = hostile. Friendly/Pleasant/Cordial are synonyms, placed as traps.", rule: "Antonym — amiable ≠ hostile.", trapcat: "Word meaning - synonym traps", level: "L3 Trap" },
    { q: "One who loves and collects books:", options: ["Bibliophile", "Bibliography", "Biography", "Bibliophobe"], answer: 0, explanation: "Bibliophile = a lover/collector of books. Bibliophobe (opposite, fear of books), Bibliography (list of sources), Biography (life story) are all close-sounding traps.", rule: "One word substitution — bibliophile.", trapcat: "Word meaning - close pairs", level: "L3 Trap" },
    { q: "'To turn a blind eye' means:", options: ["To deliberately ignore something wrong", "To become blind suddenly", "To look away in fear", "To refuse to help someone"], answer: 0, explanation: "'Turn a blind eye' = to deliberately ignore or pretend not to notice something wrong.", rule: "Idiom: turn a blind eye = deliberately ignore.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "'To be in the same boat' means:", options: ["To be in the same difficult situation as others", "To travel together", "To agree completely", "To compete against each other"], answer: 0, explanation: "'In the same boat' = facing the same difficult situation or circumstances as someone else.", rule: "Idiom: in the same boat = shared situation.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "Convert to passive voice: They have completed the survey successfully.", options: ["The survey has been completed successfully by them", "The survey was completed successfully by them", "The survey is completed successfully by them", "The survey has completed successfully"], answer: 0, explanation: "Present perfect passive: has/have + been + past participle.", rule: "Active → Passive: present perfect → has been + V3.", trapcat: "Voice conversion", level: "L2 Application" },
    { q: "Convert to indirect speech: The manager said, \"I will review your proposal tomorrow.\"", options: ["The manager said that he would review my proposal the next day", "The manager said that he will review my proposal tomorrow", "The manager said he would review my proposal tomorrow", "The manager said that he would review my proposal today"], answer: 0, explanation: "Will backshifts to would; 'tomorrow' shifts to 'the next day' in reported speech.", rule: "Backshift modal (will→would) + time reference (tomorrow→the next day).", trapcat: "Modal + time-reference backshift", level: "L3 Trap" },
    { q: "Choose the correctly spelt word.", options: ["Maintenance", "Maintainance", "Maintenence", "Maintaenance"], answer: 0, explanation: "'Maintenance' is correctly spelt — note it drops the second 'ai' pattern from 'maintain', a common source of error.", rule: "Spelling: maintenance (not maintainance).", trapcat: "Spelling", level: "L2 Application" },
    { q: "Select the part with an error: He returned back to his hometown after completing his studies abroad.", options: ["He returned back", "to his hometown", "after completing his studies", "abroad"], answer: 0, explanation: "'Return' already means 'come back' — 'returned back' is redundant.", rule: "Redundancy: return already means come back.", trapcat: "Redundancy", level: "L2 Application" }
  ]
},
{
  id: "oct1_m3", label: "1 Oct · Maths Mock", timeLimitMin: 25,
  questions: [
    { q: "35% of 320 + 25% of 200 = ?", options: ["162", "150", "170", "155"], answer: 0, explanation: "35% of 320 = 112; 25% of 200 = 50; 112+50 = 162.", rule: "Percentage of number: (percentage/100) × number.", trapcat: "Calculation", level: "L1 Direct" },
    { q: "If 40% of a number is 68, the number is:", options: ["170", "160", "180", "150"], answer: 0, explanation: "Number × 40/100 = 68 → Number = 68 × 100/40 = 170.", rule: "Reverse percentage: number = value × 100/%.", trapcat: "Reverse calculation", level: "L1 Direct" },
    { q: "A number increased by 20% gives 372. The original number is:", options: ["310", "300", "320", "295"], answer: 0, explanation: "Original × 1.20 = 372 → Original = 372/1.20 = 310.", rule: "Percentage increase reverse calculation.", trapcat: "Percentage increase", level: "L2 Application" },
    { q: "If a:b = 5:6 and b:c = 4:7, then a:c = ?", options: ["10:21", "5:7", "20:42", "9:13"], answer: 0, explanation: "a:c = (5×4):(6×7) = 20:42 = 10:21 in simplest form.", rule: "Chain ratio, then simplify.", trapcat: "Ratio chain - simplification", level: "L3 Trap" },
    { q: "The average of 12 numbers is 30. If each number is increased by 3, the new average is:", options: ["33", "30", "36", "27"], answer: 0, explanation: "If each number increases by 3, the average also increases by 3 → 30+3 = 33.", rule: "Average adjustment: new avg = old avg ± change.", trapcat: "Average property", level: "L1 Direct" },
    { q: "The average weight of 10 persons increases by 2 kg when a new person replaces one of them weighing 55 kg. What is the weight of the new person?", options: ["75 kg", "70 kg", "65 kg", "80 kg"], answer: 0, explanation: "Total increase = 10 × 2 = 20 kg. New person's weight = 55+20 = 75 kg.", rule: "Total increase = count × avg change; add to replaced person's weight.", trapcat: "Average with replacement", level: "L2 Application" },
    { q: "An article is sold for Rs.720 at a loss of 10%. What is the cost price?", options: ["Rs.800", "Rs.750", "Rs.780", "Rs.820"], answer: 0, explanation: "CP = SP/(1-loss%) = 720/0.90 = Rs.800.", rule: "CP = SP / (1 - loss%).", trapcat: "Profit-loss calculation", level: "L2 Application" },
    { q: "A trader marks his goods 40% above cost price and allows a 20% discount. His gain percent is:", options: ["12%", "10%", "15%", "20%"], answer: 0, explanation: "CP=100, MP=140, SP=140×0.8=112, Gain=12%.", rule: "Marked price + discount chain.", trapcat: "Profit-loss with discount", level: "L2 Application" },
    { q: "Marked price of an item is Rs.600, discount offered is 10%. Selling price is:", options: ["Rs.540", "Rs.560", "Rs.520", "Rs.550"], answer: 0, explanation: "SP = MP × (1-discount%) = 600×0.90 = Rs.540.", rule: "SP = MP × (1 - discount%).", trapcat: "Discount calculation", level: "L1 Direct" },
    { q: "The simple interest on Rs.2000 for 4 years at 6% per annum is:", options: ["Rs.480", "Rs.450", "Rs.500", "Rs.460"], answer: 0, explanation: "SI = P×R×T/100 = 2000×6×4/100 = Rs.480.", rule: "Simple interest formula.", trapcat: "SI calculation", level: "L1 Direct" },
    { q: "The compound interest on Rs.2000 at 10% per annum for 2 years, compounded annually, is:", options: ["Rs.420", "Rs.400", "Rs.440", "Rs.410"], answer: 0, explanation: "CI = 2000×(1.10)^2 - 2000 = 2420-2000 = Rs.420.", rule: "Compound interest formula.", trapcat: "CI calculation", level: "L2 Application" },
    { q: "In what ratio must tea worth Rs.20/kg be mixed with tea worth Rs.25/kg to get a mixture worth Rs.22/kg?", options: ["3:2", "2:3", "1:2", "3:1"], answer: 0, explanation: "By alligation: (25-22):(22-20) = 3:2 (dearer:cheaper).", rule: "Alligation: (d-c):(m-c) inverted for ratio of cheaper:dearer amounts — here (d-m):(m-c) = 3:2.", trapcat: "Alligation", level: "L2 Application" },
    { q: "A and B invest in a business in the ratio 2:3. If the total profit is Rs.1200, find B's share.", options: ["Rs.720", "Rs.480", "Rs.600", "Rs.700"], answer: 0, explanation: "Total parts = 5. B's share = (3/5)×1200 = Rs.720.", rule: "Partnership: share = (ratio part/total parts) × profit.", trapcat: "Partnership", level: "L1 Direct" },
    { q: "The ratio of ages of two brothers is 2:3, and their sum is 50. Find the older brother's age after 5 years.", options: ["35", "30", "33", "28"], answer: 0, explanation: "Older brother's share = (3/5)×50 = 30. After 5 years = 30+5 = 35.", rule: "Age ratio with sum, then add years.", trapcat: "Age calculation", level: "L1 Direct" },
    { q: "A can do a piece of work in 12 days, B in 20 days. Working together, they will complete the work in:", options: ["7.5 days", "8 days", "9 days", "10 days"], answer: 0, explanation: "Combined rate = 1/12+1/20 = 5/60+3/60=8/60=2/15. Time = 15/2 = 7.5 days.", rule: "Work together: 1/A + 1/B = 1/Combined time.", trapcat: "Time and work", level: "L2 Application" },
    { q: "A and B together can complete a work in 12 days. A alone can do it in 20 days. B alone can do it in:", options: ["30 days", "25 days", "28 days", "24 days"], answer: 0, explanation: "Together rate=1/12; A alone=1/20; B alone=1/12-1/20=5/60-3/60=2/60=1/30 → 30 days.", rule: "Work efficiency: combined - one = other.", trapcat: "Time and work", level: "L2 Application" },
    { q: "Pipe A can fill a tank in 5 hours and Pipe B in 20 hours. If both are opened together, the tank fills in:", options: ["4 hours", "3.5 hours", "4.5 hours", "5 hours"], answer: 0, explanation: "Combined rate=1/5+1/20=4/20+1/20=5/20=1/4 → 4 hours.", rule: "Pipes together: 1/A + 1/B = 1/Time.", trapcat: "Pipes and cisterns", level: "L1 Direct" },
    { q: "A train running at 54 km/h crosses a pole in 10 seconds. Find the length of the train.", options: ["150 m", "140 m", "160 m", "145 m"], answer: 0, explanation: "Speed = 54×5/18=15 m/s. Length = speed×time = 15×10 = 150 m.", rule: "Crossing a pole = covering the train's own length.", trapcat: "Train problems", level: "L2 Application" },
    { q: "A car travels a distance at 40 km/h and returns the same distance at 60 km/h. Find its average speed for the entire journey.", options: ["48 km/h", "50 km/h", "45 km/h", "52 km/h"], answer: 0, explanation: "Average speed = 2xy/(x+y) = 2×40×60/100 = 48 km/h (harmonic mean, not arithmetic mean).", rule: "Equal distances → harmonic mean 2xy/(x+y).", trapcat: "Average speed trap", level: "L2 Application" },
    { q: "A boat's upstream speed is 6 km/h and downstream speed is 8 km/h. Find the speed of the stream.", options: ["1 km/h", "2 km/h", "1.5 km/h", "0.5 km/h"], answer: 0, explanation: "Stream speed = (Downstream - Upstream)/2 = (8-6)/2 = 1 km/h.", rule: "Stream speed = (Downstream-Upstream)/2.", trapcat: "Boats and streams", level: "L1 Direct" },
    { q: "The HCF of two numbers is 12 and their LCM is 240. If one number is 48, find the other.", options: ["60", "50", "54", "56"], answer: 0, explanation: "Product = HCF×LCM = 12×240=2880. Other number = 2880/48 = 60.", rule: "Number1 × Number2 = HCF × LCM.", trapcat: "HCF-LCM", level: "L2 Application" },
    { q: "Find the largest 4-digit number exactly divisible by 12.", options: ["9996", "9988", "9992", "9984"], answer: 0, explanation: "9999/12 = 833 remainder 3, so 9999-3 = 9996.", rule: "Subtract (N mod divisor) from N.", trapcat: "Divisibility", level: "L1 Direct" },
    { q: "The angles of a triangle are in the ratio 2:3:4. Find the largest angle.", options: ["80 degrees", "90 degrees", "75 degrees", "85 degrees"], answer: 0, explanation: "Total parts=9. Largest = (4/9)×180 = 80 degrees.", rule: "Triangle angle sum = 180; divide by total parts.", trapcat: "Geometry", level: "L1 Direct" },
    { q: "The area of a circle is 154 sq cm. Find its radius. (Use pi = 22/7)", options: ["7 cm", "6 cm", "8 cm", "7.5 cm"], answer: 0, explanation: "Area = pi×r^2 → 154 = (22/7)×r^2 → r^2 = 154×7/22 = 49 → r = 7 cm.", rule: "Reverse area formula: r = sqrt(Area × 7/22).", trapcat: "Mensuration - reverse", level: "L2 Application" },
    { q: "Simplify: (5/6 + 1/3) divided by (1/2 - 1/6)", options: ["3.5", "3", "4", "2.5"], answer: 0, explanation: "Numerator: 5/6+1/3=5/6+2/6=7/6. Denominator: 1/2-1/6=3/6-1/6=2/6=1/3. Result=(7/6)/(1/3)=(7/6)×3=7/2=3.5.", rule: "Convert to single fractions, then divide by multiplying by reciprocal.", trapcat: "Simplification", level: "L2 Application" }
  ]
},
{
  id: "oct1_m4", label: "1 Oct · GS Mock", timeLimitMin: 30,
  questions: [
    { q: "Which Article of the Indian Constitution abolishes untouchability?", options: ["Article 17", "Article 15", "Article 21", "Article 23"], answer: 0, explanation: "Article 17 abolishes untouchability and forbids its practice in any form.", rule: "Article 17 — abolition of untouchability.", trapcat: "Fundamental Rights", level: "L2 Application" },
    { q: "The 'Doctrine of Basic Structure' of the Indian Constitution was propounded in which case?", options: ["Kesavananda Bharati case (1973)", "Golaknath case (1967)", "Minerva Mills case (1980)", "Maneka Gandhi case (1978)"], answer: 0, explanation: "The Kesavananda Bharati case (1973) established that Parliament cannot amend the 'basic structure' of the Constitution.", rule: "Kesavananda Bharati — Basic Structure Doctrine.", trapcat: "Landmark cases", level: "L3 Trap" },
    { q: "Who was the first Speaker of the Lok Sabha?", options: ["G.V. Mavalankar", "Sardar Hukam Singh", "N. Sanjiva Reddy", "K.S. Hegde"], answer: 0, explanation: "G.V. Mavalankar was the first Speaker of the Lok Sabha, serving from 1952.", rule: "First Lok Sabha Speaker — G.V. Mavalankar.", trapcat: "Constitutional history", level: "L2 Application" },
    { q: "The Battle of Plassey (1757), which laid the foundation of British rule in India, was fought between the British and:", options: ["Siraj-ud-Daulah, Nawab of Bengal", "Tipu Sultan", "Mir Qasim", "Shuja-ud-Daulah"], answer: 0, explanation: "The Battle of Plassey (1757) was fought between the British East India Company and Siraj-ud-Daulah, the last independent Nawab of Bengal.", rule: "Battle of Plassey — Siraj-ud-Daulah.", trapcat: "British colonial history", level: "L2 Application" },
    { q: "Which Mughal emperor is associated with the 'Din-i-Ilahi', a syncretic religious movement?", options: ["Akbar", "Jahangir", "Shah Jahan", "Aurangzeb"], answer: 0, explanation: "Akbar founded Din-i-Ilahi in 1582, blending elements of various religions.", rule: "Din-i-Ilahi — founded by Akbar.", trapcat: "Mughal history", level: "L2 Application" },
    { q: "The Tropic of Cancer passes through how many Indian states?", options: ["8", "7", "9", "6"], answer: 0, explanation: "The Tropic of Cancer passes through 8 Indian states: Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura, and Mizoram.", rule: "Tropic of Cancer — 8 Indian states.", trapcat: "Physical geography", level: "L3 Trap" },
    { q: "Which is the largest freshwater lake in India?", options: ["Wular Lake (Jammu & Kashmir)", "Chilika Lake (Odisha)", "Dal Lake (Jammu & Kashmir)", "Sambhar Lake (Rajasthan)"], answer: 0, explanation: "Wular Lake in Jammu & Kashmir is the largest freshwater lake in India. Chilika is the largest BRACKISH-water lagoon, a commonly confused distinction.", rule: "Wular = largest freshwater; Chilika = largest brackish-water lagoon.", trapcat: "Freshwater vs brackish lake trap", level: "L3 Trap" },
    { q: "Which state has the highest installed solar power capacity in India (among traditionally leading states)?", options: ["Rajasthan", "Gujarat", "Karnataka", "Tamil Nadu"], answer: 0, explanation: "Rajasthan, with its vast arid land and high solar insolation, has consistently led India in installed solar power capacity.", rule: "Rajasthan — leading solar power capacity.", trapcat: "Renewable energy geography", level: "L2 Application" },
    { q: "The Reserve Bank of India's monetary policy committee (MPC) has how many members?", options: ["6", "5", "7", "4"], answer: 0, explanation: "The Monetary Policy Committee (MPC) has 6 members — 3 from RBI and 3 external members appointed by the government.", rule: "MPC — 6 members (3 RBI + 3 external).", trapcat: "Monetary policy structure", level: "L3 Trap" },
    { q: "'Disinvestment' in the context of the Indian economy refers to:", options: ["The sale of government equity/stake in public sector enterprises", "The government investing more money into public enterprises", "Foreign companies withdrawing investment from India", "Reduction in overall government expenditure"], answer: 0, explanation: "Disinvestment means the government selling or liquidating its equity stake in public sector undertakings (PSUs).", rule: "Disinvestment — government selling PSU stake.", trapcat: "Economic terminology", level: "L2 Application" },
    { q: "Which vitamin deficiency causes the disease 'Rickets' in children?", options: ["Vitamin D", "Vitamin A", "Vitamin C", "Vitamin B12"], answer: 0, explanation: "Vitamin D deficiency causes Rickets (soft, weak bones) in children.", rule: "Vitamin D deficiency — Rickets.", trapcat: "Nutritional deficiency diseases", level: "L2 Application" },
    { q: "Which gas is most responsible for the depletion of the ozone layer?", options: ["Chlorofluorocarbons (CFCs)", "Carbon dioxide", "Methane", "Sulphur dioxide"], answer: 0, explanation: "Chlorofluorocarbons (CFCs), once widely used in refrigerants and aerosols, are the primary cause of ozone layer depletion.", rule: "CFCs — primary ozone depletion cause.", trapcat: "Environmental chemistry", level: "L2 Application" },
    { q: "The process by which plants lose water in the form of vapour through their leaves is called:", options: ["Transpiration", "Respiration", "Photosynthesis", "Osmosis"], answer: 0, explanation: "Transpiration is the loss of water vapour from plant leaves through stomata.", rule: "Transpiration — water loss from leaves.", trapcat: "Plant physiology", level: "L1 Direct" },
    { q: "Who is credited with founding the Indian National Congress in 1885?", options: ["A.O. Hume", "Dadabhai Naoroji", "W.C. Bonnerjee", "Surendranath Banerjee"], answer: 0, explanation: "A.O. Hume, a retired British civil servant, is credited with founding the Indian National Congress in 1885. W.C. Bonnerjee was its first President, a commonly confused distinction.", rule: "A.O. Hume founded INC; W.C. Bonnerjee was its first President.", trapcat: "Founder vs first president trap", level: "L3 Trap" },
    { q: "The 'Poona Pact' (1932) was signed between Mahatma Gandhi and:", options: ["B.R. Ambedkar", "Muhammad Ali Jinnah", "Subhas Chandra Bose", "Madan Mohan Malaviya"], answer: 0, explanation: "The Poona Pact (1932) was signed between Gandhi and Ambedkar, replacing separate electorates for the Depressed Classes with reserved seats in a joint electorate.", rule: "Poona Pact — Gandhi and Ambedkar.", trapcat: "Freedom movement agreements", level: "L2 Application" },
    { q: "Which Indian state is the largest producer of coffee?", options: ["Karnataka", "Kerala", "Tamil Nadu", "Andhra Pradesh"], answer: 0, explanation: "Karnataka (particularly the Kodagu/Coorg region) is India's largest coffee-producing state.", rule: "Karnataka — largest coffee producer.", trapcat: "Agricultural geography", level: "L2 Application" },
    { q: "The 'Sangam' literature belongs to which period and region?", options: ["Ancient Tamil Nadu (roughly 300 BCE - 300 CE)", "Medieval Bengal", "Ancient Gujarat", "Medieval Karnataka"], answer: 0, explanation: "Sangam literature is a body of ancient Tamil poetic works composed roughly between 300 BCE and 300 CE.", rule: "Sangam literature — ancient Tamil Nadu.", trapcat: "Ancient literature", level: "L2 Application" },
    { q: "Which of the following is NOT one of the three organs of the State as per the doctrine of Separation of Powers?", options: ["Bureaucracy", "Legislature", "Executive", "Judiciary"], answer: 0, explanation: "The classical Separation of Powers doctrine identifies three organs: Legislature, Executive, and Judiciary. Bureaucracy is part of the Executive machinery, not a separate fourth organ.", rule: "Three organs: Legislature, Executive, Judiciary (Bureaucracy is part of Executive).", trapcat: "Political theory", level: "L2 Application" },
    { q: "The 'Simon Commission' (1928), which visited India to review constitutional reforms, was boycotted primarily because:", options: ["It did not include any Indian members", "It proposed to abolish provincial autonomy", "It recommended separate electorates for all communities", "It was formed without British parliamentary approval"], answer: 0, explanation: "The Simon Commission was boycotted with 'Simon Go Back' protests because it had no Indian members despite reviewing India's constitutional future.", rule: "Simon Commission boycotted — all-British composition, no Indians.", trapcat: "Freedom movement protests", level: "L2 Application" },
    { q: "Which layer of the atmosphere contains the ozone layer that protects Earth from harmful UV radiation?", options: ["Stratosphere", "Troposphere", "Mesosphere", "Thermosphere"], answer: 0, explanation: "The ozone layer is located in the stratosphere, roughly 15-35 km above Earth's surface.", rule: "Ozone layer — located in the stratosphere.", trapcat: "Atmospheric layers", level: "L2 Application" },
    { q: "The 'Gini Coefficient' is a statistical measure used to represent:", options: ["Income or wealth inequality within a nation", "Rate of inflation", "Gross Domestic Product growth rate", "Literacy rate"], answer: 0, explanation: "The Gini Coefficient measures income or wealth inequality within a population, ranging from 0 (perfect equality) to 1 (perfect inequality).", rule: "Gini Coefficient — measure of inequality.", trapcat: "Economic indicators", level: "L2 Application" },
    { q: "Which Indian classical dance form originated in Tamil Nadu and is traditionally associated with temple worship?", options: ["Bharatanatyam", "Kathak", "Odissi", "Manipuri"], answer: 0, explanation: "Bharatanatyam originated in Tamil Nadu temples, traditionally performed by devadasis as a form of worship.", rule: "Bharatanatyam — Tamil Nadu classical dance.", trapcat: "Classical dance forms", level: "L2 Application" },
    { q: "Which committee recommended the establishment of NITI Aayog to replace the Planning Commission?", options: ["No committee — it was a direct Cabinet decision in 2015", "Ashok Chawla Committee", "Bibek Debroy Committee (post-facto review only)", "C. Rangarajan Committee"], answer: 0, explanation: "NITI Aayog was established via a direct Union Cabinet resolution on 1 January 2015, not through a formal recommending committee — a fact that itself is often tested as a trap since most institutional changes DO follow committee recommendations.", rule: "NITI Aayog — direct Cabinet decision, not committee-recommended.", trapcat: "Institutional history - direct decision trap", level: "L3 Trap" },
    { q: "The 'Namami Gange' programme is primarily aimed at:", options: ["Conservation and rejuvenation of the Ganga river", "Afforestation along the Himalayan foothills", "Rural electrification in the Gangetic plains", "Flood control in the Brahmaputra basin"], answer: 0, explanation: "Namami Gange is a flagship programme for the conservation and rejuvenation of the National River Ganga, covering pollution abatement and river-front development.", rule: "Namami Gange — Ganga conservation programme.", trapcat: "Government schemes", level: "L1 Direct" },
    { q: "Which blood vessel carries oxygenated blood from the lungs back to the heart?", options: ["Pulmonary vein", "Pulmonary artery", "Aorta", "Vena cava"], answer: 0, explanation: "The pulmonary vein carries oxygenated blood from the lungs to the heart's left atrium — the one vein in the body that carries oxygen-rich blood (veins usually carry deoxygenated blood).", rule: "Pulmonary vein — the exception that carries oxygenated blood.", trapcat: "Circulatory system - vein/artery exception", level: "L3 Trap" }
  ]
},
{
  id: "oct2_m1", label: "2 Oct · Morning English Mock (Deep)", timeLimitMin: 25,
  questions: [
    { q: "The findings of the research team, which had spent nearly three years studying migratory patterns, was presented at the international conference last month.", options: ["The findings of the research team,", "which had spent nearly three years studying migratory patterns,", "was presented at", "the international conference last month"], answer: 2, explanation: "The true subject is 'findings' (plural), not 'team' — despite the long embedded clause about the team, it should be 'were presented', not 'was presented'.", rule: "Identify the real subject before an embedded relative clause; do not let the clause's own noun (team, singular) hijack the verb agreement.", trapcat: "Embedded clause - subject-verb agreement", level: "L3 Trap" },
    { q: "Despite having been warned repeatedly by his doctor about the risks, he continued to ignoring the advice and carried on with his unhealthy habits.", options: ["Despite having been warned repeatedly", "by his doctor about the risks,", "he continued to ignoring", "the advice and carried on"], answer: 2, explanation: "'Continued to' must be followed by the bare infinitive 'ignore', not the gerund 'ignoring' — it should be 'continued to ignore'.", rule: "'Continue to' + base verb (infinitive without 'to' being dropped is incorrect here — the infinitive form itself, e.g. 'to ignore', is required, not 'to ignoring').", trapcat: "Infinitive vs gerund after 'continued to'", level: "L3 Trap" },
    { q: "Not only did the new policy fail to reduce costs, but it also created several unintended consequences that the committee had not anticipating.", options: ["Not only did the new policy fail", "to reduce costs,", "but it also created several unintended consequences", "that the committee had not anticipating"], answer: 3, explanation: "'Had not' must be followed by a past participle, not a gerund — it should be 'had not anticipated', not 'had not anticipating'.", rule: "Past perfect negative: had not + past participle.", trapcat: "Past perfect tense error", level: "L3 Trap" },
    { q: "The proposal, along with the supporting documents that had been submitted earlier, were rejected by the review board without explanation.", options: ["The proposal, along with", "the supporting documents that had been submitted earlier,", "were rejected by the review board", "without explanation"], answer: 2, explanation: "'Along with' does not pluralise the subject — 'the proposal' remains the true singular subject, so it should be 'was rejected', not 'were rejected'.", rule: "'Along with' does not make the subject plural, even with a long embedded phrase following it.", trapcat: "Along with trap (embedded)", level: "L3 Trap" },
    { q: "Improve: The board members, who had been debating the merger for hours, was finally able to reach a consensus decision.", options: ["were finally able to reach", "was finally able to reaching", "have finally able to reach", "No improvement"], answer: 0, explanation: "'Board members' (plural) is the true subject — the embedded relative clause does not change this. It should be 'were finally able to reach', not 'was'.", rule: "Match the verb to the true plural subject despite an intervening relative clause.", trapcat: "Embedded clause agreement", level: "L2 Application" },
    { q: "Improve: It is essential that every employee follows the updated safety protocol without exception.", options: ["that every employee follow", "that every employee is following", "that every employee followed", "No improvement"], answer: 0, explanation: "After 'it is essential that', the subjunctive mood requires the bare base form of the verb ('follow'), regardless of the subject's number — not 'follows'.", rule: "Subjunctive mood after essential/important/necessary that: base verb form, no -s.", trapcat: "Subjunctive mood", level: "L3 Trap" },
    { q: "Improve: Having completed the assignment ahead of schedule, the manager's praise was well deserved by the team.", options: ["the team's efforts well deserved the manager's praise", "the team deserved the manager's praise", "the manager praised the team, well deserved", "No improvement"], answer: 1, explanation: "This is a dangling modifier — 'Having completed the assignment' should logically modify 'the team' (who completed it), not 'the manager's praise', which cannot itself complete an assignment.", rule: "The subject immediately after an introductory participial phrase must be the one performing that action.", trapcat: "Dangling modifier", level: "L3 Trap" },
    { q: "The committee, having reviewed all the applications submitted by the candidates, has decided to shortlist five of them for the ___ round.", options: ["subsequent", "consequent", "resultant", "concurrent"], answer: 0, explanation: "'Subsequent' means following in time/order — the next round after shortlisting. 'Consequent' means resulting from something, 'resultant' is similar, and 'concurrent' means happening at the same time.", rule: "Subsequent = following in sequence; distinguish from consequent (resulting from) and concurrent (simultaneous).", trapcat: "Close vocabulary in context", level: "L3 Trap" },
    { q: "Given the ___ nature of the evidence presented, the jury found it difficult to reach a unanimous verdict.", options: ["equivocal", "unequivocal", "equitable", "eloquent"], answer: 0, explanation: "'Equivocal' means open to more than one interpretation, ambiguous — matching the jury's difficulty. 'Unequivocal' means the opposite (completely clear), which would contradict the sentence's logic.", rule: "Equivocal = ambiguous; watch for the 'un-' prefix flipping the meaning entirely in a similar-looking trap option.", trapcat: "Prefix-flip vocabulary trap", level: "L3 Trap" },
    { q: "The two companies, despite being fierce competitors for years, decided to ___ their resources for this one joint venture.", options: ["pool", "poll", "pull", "pole"], answer: 0, explanation: "'Pool' (as a verb) means to combine resources together. 'Poll' relates to voting/surveys, 'pull' means to drag, 'pole' is a long rod — all homophones/near-homophones of 'pool' used as traps.", rule: "Pool (combine resources) vs poll/pull/pole — distinguish these commonly confused homophone-adjacent words.", trapcat: "Homophone trap", level: "L3 Trap" },
    { q: "Select the correctly punctuated sentence.", options: ["The manager said, \"We will announce the results by Friday.\"", "The manager said \"We will announce the results by Friday\".", "The manager said, \"We will announce the results by Friday\".", "The manager said \"We will announce the results by Friday.\""], answer: 0, explanation: "The comma after 'said' introduces the quotation, the quoted sentence begins with a capital letter, and the closing period sits INSIDE the closing quotation mark.", rule: "Direct speech punctuation: comma before the quote, period inside the closing quotation mark.", trapcat: "Punctuation", level: "L2 Application" },
    { q: "Rearrange: P. The company's stock price plummeted overnight. Q. Investors had grown increasingly wary after the earnings report. R. An anonymous whistleblower revealed accounting irregularities. S. Regulators launched a formal investigation within days.", options: ["R,Q,P,S", "Q,R,P,S", "R,P,Q,S", "Q,P,R,S"], answer: 0, explanation: "The whistleblower's revelation (R) comes first, causing investor wariness (Q), which triggers the stock price collapse (P), followed by the regulatory investigation (S).", rule: "Trace each sentence's cause-effect trigger before ordering — the whistleblower's reveal is the root cause that sets off the rest.", trapcat: "Sentence sequencing - root cause identification", level: "L3 Trap" },
    { q: "Synonym of CIRCUMSPECT:", options: ["Cautious", "Reckless", "Careless", "Impulsive"], answer: 0, explanation: "Circumspect = careful to consider all circumstances before acting; cautious.", rule: "Circumspect = cautious, wary of consequences.", trapcat: "Vocabulary", level: "L2 Application" },
    { q: "Antonym of INTREPID:", options: ["Timid", "Brave", "Bold", "Daring"], answer: 0, explanation: "Intrepid = fearless, brave; opposite = timid. Brave/Bold/Daring are all synonyms, placed as traps.", rule: "Antonym — intrepid ≠ timid.", trapcat: "Word meaning - synonym traps", level: "L3 Trap" },
    { q: "One who is knowledgeable about many different subjects:", options: ["Polymath", "Polyglot", "Pedant", "Pundit"], answer: 0, explanation: "Polymath = a person with knowledge across many different fields. Polyglot = someone who speaks many LANGUAGES (not subjects), Pedant = overly concerned with minor details/rules, Pundit = an expert/commentator in one specific area.", rule: "Polymath (many subjects) vs Polyglot (many languages) — a frequent close-pair confusion.", trapcat: "Close word-pair trap", level: "L3 Trap" },
    { q: "'To hit the nail on the head' means:", options: ["To describe something exactly and accurately", "To cause an accident", "To fail at a task completely", "To work very hard on a project"], answer: 0, explanation: "'Hit the nail on the head' = to describe or identify something precisely and correctly.", rule: "Idiom: hit the nail on the head = precisely correct.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "'To be a fish out of water' means:", options: ["To feel awkward or out of place in a situation", "To struggle to breathe", "To be extremely thirsty", "To swim very well"], answer: 0, explanation: "'Fish out of water' = to feel uncomfortable or out of place in an unfamiliar situation.", rule: "Idiom: fish out of water = feeling out of place.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "Convert to passive voice: The board must have approved the budget before the deadline.", options: ["The budget must have been approved by the board before the deadline", "The budget must have approved by the board before the deadline", "The budget must be approved by the board before the deadline", "The budget had to be approved by the board before the deadline"], answer: 0, explanation: "Modal perfect passive: 'must have' + been + past participle — 'must have been approved'.", rule: "Modal + have + been + V3 for a modal perfect passive construction.", trapcat: "Modal perfect passive", level: "L3 Trap" },
    { q: "Convert to indirect speech: The doctor said to the patient, \"You should reduce your salt intake and exercise regularly.\"", options: ["The doctor advised the patient to reduce his salt intake and exercise regularly", "The doctor said that the patient should reduce his salt intake and exercise regularly", "The doctor told the patient reduce his salt intake and exercise regularly", "The doctor said to reduce the salt intake and exercising regularly"], answer: 0, explanation: "An advice-giving 'should' statement converts to 'advised + object + to + base verb' in indirect speech, with two parallel actions (reduce, exercise) both converted to infinitives.", rule: "'Should' advice converts to 'advised to' + infinitive, applied consistently to both parallel actions.", trapcat: "Advice narration with parallel structure", level: "L3 Trap" },
    { q: "Choose the correctly spelt word.", options: ["Bureaucracy", "Beaurocracy", "Bureaucracy", "Burocracy"], answer: 0, explanation: "'Bureaucracy' is correctly spelt — note the 'eau' sequence borrowed from French, a common source of error.", rule: "Spelling: bureaucracy has the French-origin 'eau' spelling pattern.", trapcat: "Spelling", level: "L2 Application" },
    { q: "Select the part with an error: The twins were so identical in appearance and mannerism that even their closest friends often confuses one for the other.", options: ["The twins were so identical", "in appearance and mannerism", "that even their closest friends", "often confuses one for the other"], answer: 3, explanation: "'Friends' (plural) is the subject of this clause — it should be 'often confuse', not 'often confuses'.", rule: "Match the verb to its own clause's subject (friends, plural), independent of the main clause's subject earlier in the sentence.", trapcat: "Subject-verb agreement in subordinate clause", level: "L2 Application" },
    { q: "Select the part with an error: The report clearly indicate that the company's revenue has declined steadily over the past three quarters.", options: ["The report clearly indicate", "that the company's revenue", "has declined steadily", "over the past three quarters"], answer: 0, explanation: "'The report' is singular — should be 'indicates', not 'indicate'.", rule: "Singular subject 'report' requires singular verb 'indicates'.", trapcat: "Subject-verb agreement", level: "L2 Application" },
    { q: "Improve: The reason why he resigned was because he disagreed with the company's new direction.", options: ["The reason why he resigned was that", "The reason he resigned was because", "The reason for his resignation is because", "No improvement"], answer: 0, explanation: "'The reason...was because' is redundant (both 'reason' and 'because' express causation) — the correct form is 'the reason...was that'.", rule: "Avoid 'reason...because' redundancy; use 'reason...that' instead.", trapcat: "Redundancy - reason because", level: "L3 Trap" },
    { q: "Select the part with an error: Between you and I, I think the new proposal is far more practical than the original one.", options: ["Between you and I,", "I think the new proposal", "is far more practical", "than the original one"], answer: 0, explanation: "'Between' is a preposition and must be followed by object pronouns — it should be 'between you and me', not 'between you and I'.", rule: "Prepositions take object pronouns (me, him, her), never subject pronouns (I, he, she).", trapcat: "Preposition + pronoun case error", level: "L3 Trap" },
    { q: "Improve: Each of the applicants were required to submit their portfolio along with a written statement of purpose.", options: ["Each of the applicants was required", "Each of the applicant were required", "Each of the applicants have required", "No improvement"], answer: 0, explanation: "'Each' is always singular, regardless of the plural noun that follows — it should be 'was required', not 'were required'.", rule: "Each + of + plural noun still takes a singular verb.", trapcat: "Each + plural noun", level: "L2 Application" }
  ]
},
{
  id: "oct2_m2", label: "2 Oct · Evening English Mock (Deep)", timeLimitMin: 25,
  questions: [
    { q: "The findings of the survey, which involved over ten thousand respondents across various age groups, reveals a significant shift in consumer preferences.", options: ["The findings of the survey,", "which involved over ten thousand respondents", "across various age groups, reveals", "a significant shift in consumer preferences"], answer: 2, explanation: "The true subject is 'findings' (plural) — the long embedded clause about the survey does not change this. It should be 'reveal', not 'reveals'.", rule: "Identify the real subject (findings, plural) before a long embedded relative clause; do not let the clause's own singular noun (survey) hijack the verb.", trapcat: "Embedded clause - subject-verb agreement", level: "L3 Trap" },
    { q: "Improve: The professor insisted that the assignment be submit before the end of the week without any extensions.", options: ["be submitted", "was submitted", "is submitted", "No improvement"], answer: 0, explanation: "After 'insisted that', the subjunctive mood requires 'be' + past participle in a passive construction — 'be submitted', not 'be submit'.", rule: "Subjunctive passive: insisted that + subject + be + past participle.", trapcat: "Subjunctive passive", level: "L3 Trap" },
    { q: "Having been informed of the delay well in advance, the passengers' frustration was somewhat lessened by the airline's prompt communication.", options: ["the passengers were somewhat less frustrated", "the passengers' frustration lessened somewhat by itself", "the airline lessened the passengers, frustration", "No improvement"], answer: 0, explanation: "This is a dangling modifier — 'Having been informed' should modify 'the passengers' (who were informed), not 'the passengers' frustration', which cannot itself be 'informed'.", rule: "The subject immediately following an introductory participial phrase must be the one who performed/received that action.", trapcat: "Dangling modifier", level: "L3 Trap" },
    { q: "Neither the CEO nor the board members, who had reviewed the merger proposal extensively, was fully convinced of its long-term viability.", options: ["Neither the CEO nor the board members,", "who had reviewed the merger proposal extensively,", "was fully convinced", "of its long-term viability"], answer: 2, explanation: "Neither/nor agrees with the NEARER subject — 'board members' (plural) is nearer, so it should be 'were fully convinced', not 'was'.", rule: "Neither/nor → verb agrees with the nearer subject, regardless of an intervening embedded clause.", trapcat: "Neither/nor with embedded clause", level: "L3 Trap" },
    { q: "It is imperative that the organisation reviews its data protection policies in light of the recent regulatory changes.", options: ["that the organisation review", "that the organisation reviewing", "that the organisation reviewed", "No improvement"], answer: 0, explanation: "After 'it is imperative that', the subjunctive mood requires the bare base verb form — 'review', not 'reviews'.", rule: "Subjunctive mood after imperative/essential/vital that: base verb form, no -s.", trapcat: "Subjunctive mood", level: "L3 Trap" },
    { q: "The witness's testimony, corroborated by several pieces of forensic evidence gathered at the scene, was ultimately found ___ by the jury.", options: ["credible", "credulous", "creditable", "incredulous"], answer: 0, explanation: "'Credible' = believable, convincing. 'Credulous' means too easily believing others (a trait of a person, not evidence), 'creditable' means praiseworthy, 'incredulous' means unwilling to believe.", rule: "Credible (believable) vs credulous (gullible) — a classic close-pair vocabulary trap.", trapcat: "Close vocabulary trap", level: "L3 Trap" },
    { q: "Given the company's ___ financial position, further expansion at this stage would be an unnecessarily risky move.", options: ["precarious", "precocious", "precursory", "precise"], answer: 0, explanation: "'Precarious' means uncertain, unstable, dangerously balanced — fitting a risky financial situation. Precocious relates to early development (of a child), precursory means preceding, precise means exact.", rule: "Precarious = unstable/risky; do not confuse with similarly-spelled but unrelated words.", trapcat: "Spelling-similar vocabulary trap", level: "L3 Trap" },
    { q: "The two departments finally agreed to ___ their efforts on the joint research initiative after months of miscommunication.", options: ["coordinate", "corroborate", "collaborate", "correlate"], answer: 0, explanation: "'Coordinate' fits best here (organize joint efforts together); while 'collaborate' is close in meaning, the phrase 'coordinate their efforts' is the more precise, standard collocation compared to 'collaborate their efforts', which is not idiomatic English.", rule: "Coordinate efforts (standard collocation) vs collaborate ON something — check which verb takes 'efforts' as a direct object naturally.", trapcat: "Collocation precision", level: "L3 Trap" },
    { q: "Select the correctly punctuated sentence.", options: ["Although the meeting was postponed, the agenda remained unchanged.", "Although, the meeting was postponed the agenda remained unchanged.", "Although the meeting was postponed the agenda, remained unchanged.", "Although the meeting was postponed; the agenda remained unchanged."], answer: 0, explanation: "A comma correctly separates the introductory subordinate clause ('Although the meeting was postponed') from the main clause, with no comma needed after 'Although' itself and no semicolon required.", rule: "Comma after an introductory subordinate clause, placed at the clause boundary, not mid-clause.", trapcat: "Punctuation - subordinate clause", level: "L2 Application" },
    { q: "Rearrange: P. The village had relied on a single well for generations. Q. Engineers proposed a new pipeline connecting it to the reservoir. R. That well ran dry during an unusually harsh summer. S. Residents were forced to walk several kilometres for water. ", options: ["P,R,S,Q", "P,Q,R,S", "R,P,S,Q", "P,S,R,Q"], answer: 0, explanation: "Background (P: village relied on the well) -> problem (R: well ran dry) -> consequence (S: residents forced to walk) -> solution (Q: engineers propose pipeline).", rule: "Background -> problem -> consequence -> solution is a common four-part narrative structure to identify.", trapcat: "Sentence sequencing - narrative structure", level: "L3 Trap" },
    { q: "Synonym of PRAGMATIC:", options: ["Practical", "Idealistic", "Theoretical", "Impractical"], answer: 0, explanation: "Pragmatic = dealing with things sensibly and realistically; practical.", rule: "Pragmatic = practical, realistic approach.", trapcat: "Vocabulary", level: "L2 Application" },
    { q: "Antonym of METICULOUS:", options: ["Careless", "Precise", "Thorough", "Careful"], answer: 0, explanation: "Meticulous = showing great attention to detail; very careful. Opposite = careless. Precise/Thorough/Careful are all synonyms, placed as traps.", rule: "Antonym — meticulous ≠ careless.", trapcat: "Word meaning - synonym traps", level: "L3 Trap" },
    { q: "One who withdraws from social interaction and prefers to be alone:", options: ["Recluse", "Renegade", "Reprobate", "Recidivist"], answer: 0, explanation: "Recluse = a person who lives in seclusion, avoiding others. Renegade = one who deserts a cause, Reprobate = an unprincipled person, Recidivist = one who repeatedly relapses into crime — all 'Re-' words used as sound-alike traps.", rule: "Recluse (seeks solitude) vs Renegade/Reprobate/Recidivist — all share the 'Re-' prefix but mean entirely different things.", trapcat: "Prefix-cluster vocabulary trap", level: "L3 Trap" },
    { q: "'To let sleeping dogs lie' means:", options: ["To avoid raising a topic that might cause trouble", "To allow pets to rest undisturbed", "To ignore a problem until it grows worse", "To trust someone completely"], answer: 0, explanation: "'Let sleeping dogs lie' = to deliberately avoid interfering with a situation that could cause problems if disturbed.", rule: "Idiom: let sleeping dogs lie = avoid stirring up trouble.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "'To be caught between a rock and a hard place' means:", options: ["To be faced with two equally difficult choices", "To be physically trapped somewhere", "To make an easy decision quickly", "To avoid making any decision at all"], answer: 0, explanation: "'Caught between a rock and a hard place' = facing a choice between two equally unpleasant or difficult options.", rule: "Idiom: rock and a hard place = dilemma between two bad choices.", trapcat: "Idiom interpretation", level: "L2 Application" },
    { q: "Convert to passive voice: They should have completed the project by now.", options: ["The project should have been completed by now", "The project should have completed by now", "The project should be completed by now", "The project had to be completed by now"], answer: 0, explanation: "Modal perfect passive: 'should have' + been + past participle — 'should have been completed'.", rule: "Modal + have + been + V3 for modal perfect passive.", trapcat: "Modal perfect passive", level: "L3 Trap" },
    { q: "Convert to indirect speech: The coach said to the team, \"You must practice harder if you want to win the championship.\"", options: ["The coach told the team that they had to practice harder if they wanted to win the championship", "The coach said the team must practice harder if they want to win the championship", "The coach told the team you must practice harder if you want to win the championship", "The coach said that the team must practiced harder if they wanted to win the championship"], answer: 0, explanation: "'Must' (obligation) typically backshifts to 'had to' in reported speech; the conditional clause ('if you want') also backshifts consistently ('if they wanted').", rule: "Must (obligation) -> had to; backshift BOTH the main clause and the embedded conditional clause consistently.", trapcat: "Modal backshift with conditional clause", level: "L3 Trap" },
    { q: "Choose the correctly spelt word.", options: ["Millennium", "Millenium", "Millenneum", "Milennium"], answer: 0, explanation: "'Millennium' is correctly spelt with double L and double N — a very commonly misspelt word for exactly this reason.", rule: "Spelling: millennium needs BOTH double L and double N.", trapcat: "Spelling", level: "L2 Application" },
    { q: "Select the part with an error: Scarcely had the negotiations begun when one of the delegates walked out in protest, and this action derail the entire summit.", options: ["Scarcely had the negotiations begun", "when one of the delegates walked out in protest,", "and this action derail", "the entire summit"], answer: 2, explanation: "'This action' is singular and the sentence is in past tense (matching 'walked out') — it should be 'derailed', not 'derail'.", rule: "Maintain consistent past tense across a compound sentence; a singular subject needs the correctly inflected past-tense verb.", trapcat: "Tense consistency in compound sentence", level: "L2 Application" },
    { q: "Improve: The number of students who has enrolled for the summer programme have exceeded all previous years' records.", options: ["The number of students who have enrolled has exceeded", "The number of students who has enrolled have exceeded", "The number of student who have enrolled has exceeded", "No improvement"], answer: 0, explanation: "Within 'who have enrolled', 'who' refers to 'students' (plural), needing 'have'. But 'the number...has exceeded' is correct since 'the number of' is the singular main subject — combining both fixes gives 'who have enrolled has exceeded'.", rule: "Two separate agreement points in one sentence: the relative clause verb (matches 'students', plural) and the main clause verb (matches 'the number', singular).", trapcat: "Double agreement point - relative clause + main subject", level: "L3 Trap" },
    { q: "Select the part with an error: The reason the flight was delay was due to unexpected mechanical issues discovered during the pre-flight inspection.", options: ["The reason the flight was delay", "was due to unexpected mechanical issues", "discovered during", "the pre-flight inspection"], answer: 0, explanation: "'Was delay' is incorrect — the passive past tense requires the past participle 'delayed', giving 'the flight was delayed'.", rule: "Passive voice past tense: was/were + past participle (delayed), not the base form.", trapcat: "Passive voice - wrong verb form", level: "L2 Application" },
    { q: "Improve: Not only was the presentation informative, but also it was engaging enough to hold the audience's attention throughout.", options: ["but it was also engaging enough", "but also was it engaging enough", "but it also was engaging enough to", "No improvement"], answer: 0, explanation: "The correlative pair 'not only...but also' requires parallel structure — 'not only WAS the presentation' pairs with 'but IT WAS also', keeping the subject-verb order consistent, not 'but also it was'.", rule: "Not only...but also requires parallel grammatical structure on both sides.", trapcat: "Correlative conjunction - parallel structure", level: "L3 Trap" },
    { q: "Select the part with an error: Between the two finalists, the judges found it difficult deciding who deserved the award more.", options: ["Between the two finalists,", "the judges found it difficult", "deciding who deserved", "the award more"], answer: 1, explanation: "'Found it difficult' should be followed by a full infinitive construction — 'found it difficult TO DECIDE', not 'found it difficult deciding'.", rule: "'Find it + adjective' is followed by a 'to + verb' infinitive, not a gerund.", trapcat: "Infinitive after 'find it difficult'", level: "L3 Trap" },
    { q: "Improve: The government has announced a series of measures that will hopefully mitigating the impact of inflation on low-income households.", options: ["that will hopefully mitigate", "that hopefully will mitigating", "that will hopefully mitigated", "No improvement"], answer: 0, explanation: "'Will' must be followed by the bare base verb — 'will mitigate', not 'will mitigating'.", rule: "Modal 'will' + base verb, never a gerund or past form.", trapcat: "Modal + base verb", level: "L2 Application" },
    { q: "One who is excessively concerned with formal rules and book knowledge, rather than practical understanding:", options: ["Pedant", "Prodigy", "Protagonist", "Proponent"], answer: 0, explanation: "Pedant = a person overly concerned with minor details, rules, or formal book-learning rather than practical sense. Prodigy = a highly talented young person, Protagonist = the main character in a story, Proponent = one who argues in favour of something.", rule: "Pedant = fussy about rules/formal correctness, not practical wisdom.", trapcat: "Word meaning - specialization", level: "L3 Trap" }
  ]
},
{
  id: "oct2_m3", label: "2 Oct · Maths Mock (Deep)", timeLimitMin: 30,
  questions: [
    { q: "A quantity increases by 25%, then decreases by 20%, then increases by 10%. Find the net percentage change.", options: ["10% increase", "15% increase", "5% increase", "20% increase"], answer: 0, explanation: "Combined multiplier = 1.25 x 0.80 x 1.10 = 1.10. Net change = 10% increase.", rule: "Combine all successive multipliers into one factor before comparing to 1.", trapcat: "Chained percentage", level: "L3 Trap" },
    { q: "A man sells two watches, each for Rs.1200. On one he gains 20% and on the other he loses 20%. Find his overall loss or gain percentage.", options: ["4% loss", "No profit no loss", "4% gain", "2% loss"], answer: 0, explanation: "When the same SP gives x% profit on one item and x% loss on another, the net result is always a loss of x^2/100 percent. Here x=20, so loss=400/100=4%.", rule: "Same SP, +x% and -x% => always a net loss of x^2/100 percent.", trapcat: "Two-item profit-loss trap", level: "L3 Trap" },
    { q: "The difference between compound interest and simple interest on a sum for 2 years at 10% per annum is Rs.45. Find the sum.", options: ["Rs.4,500", "Rs.4,000", "Rs.4,800", "Rs.5,000"], answer: 0, explanation: "For 2 years, CI-SI difference = P(r/100)^2. So P = 45/(0.10)^2 = 45/0.01 = Rs.4,500.", rule: "2-year CI-SI difference = P(r/100)^2.", trapcat: "Reverse CI-SI", level: "L3 Trap" },
    { q: "Pipe A can fill a tank in 6 hours, Pipe B in 9 hours, and outlet Pipe C can empty it in 18 hours. If all three are opened together, how long will it take to fill the tank?", options: ["4.5 hours", "5 hours", "4 hours", "6 hours"], answer: 0, explanation: "Combined rate = 1/6+1/9-1/18 = 3/18+2/18-1/18 = 4/18 = 2/9. Time = 9/2 = 4.5 hours.", rule: "Outlet rate is subtracted from the combined inlet rate.", trapcat: "Pipes and cisterns", level: "L2 Application" },
    { q: "Two trains, 120 m and 180 m long, run towards each other on parallel tracks at 45 km/h and 63 km/h. Find the time they take to cross each other.", options: ["10 seconds", "12 seconds", "9 seconds", "11 seconds"], answer: 0, explanation: "Relative speed (opposite directions) = 45+63=108 km/h = 108x5/18=30 m/s. Total length=120+180=300 m. Time=300/30=10 seconds.", rule: "Opposite directions: add speeds; divide total length by relative speed.", trapcat: "Train crossing - opposite direction", level: "L2 Application" },
    { q: "A can complete a work in 10 days. He works alone for 6 days, after which B (who can complete the work alone in 10 days) joins him. In how many more days will the work be completed?", options: ["2 days", "3 days", "1.5 days", "2.5 days"], answer: 0, explanation: "A's rate=1/10. Work done in 6 days=6/10=0.6, remaining=0.4. Combined rate (A+B, both 1/10)=1/5. Remaining days=0.4/(1/5)=2.", rule: "Compute work done before the join, then use the combined rate for the remainder.", trapcat: "Staggered work", level: "L2 Application" },
    { q: "If a:b = 2:3 and b:c = 5:4, find a:c.", options: ["5:6", "10:12", "4:5", "6:5"], answer: 0, explanation: "a:c = (2x5):(3x4) = 10:12 = 5:6 in simplest form.", rule: "Chain ratio, then simplify.", trapcat: "Ratio chain - simplification", level: "L2 Application" },
    { q: "A container has 60 litres of milk-water mixture in the ratio 2:1. If 20 litres of pure water is added, find the new ratio of milk to water.", options: ["1:1", "2:3", "4:5", "3:4"], answer: 0, explanation: "Milk=40L, Water=20L. Adding 20L water: water=40L. New ratio = 40:40 = 1:1.", rule: "Milk stays fixed when only water is added.", trapcat: "Mixture dilution", level: "L2 Application" },
    { q: "The cost price of an article is Rs.100. It is marked up by 50% and then sold at a discount of 20%. Find the overall gain percentage.", options: ["20%", "25%", "15%", "30%"], answer: 0, explanation: "MP=150, SP=150x0.8=120. Gain=20 on CP100, gain%=20%.", rule: "Compute MP from markup, then SP from discount on MP, then gain% on original CP.", trapcat: "Markup + discount chain", level: "L2 Application" },
    { q: "A rectangle's diagonal is 20 cm and its length is 16 cm. Find its breadth.", options: ["12 cm", "10 cm", "14 cm", "13 cm"], answer: 0, explanation: "Breadth = sqrt(diagonal^2 - length^2) = sqrt(400-256) = sqrt(144) = 12 cm.", rule: "Apply Pythagoras: diagonal^2 = length^2 + breadth^2.", trapcat: "Rectangle geometry", level: "L2 Application" },
    { q: "If tanA = 8/15 and A is acute, find the value of (sinA + cosA)/(sinA - cosA).", options: ["-23/7", "23/7", "-7/23", "7/23"], answer: 0, explanation: "From tanA=8/15 (8-15-17 triangle), sinA=8/17, cosA=15/17. (sinA+cosA)/(sinA-cosA) = (23/17)/(-7/17) = -23/7.", rule: "Build sinA, cosA from the implied right triangle, watch the sign.", trapcat: "Trig ratio identity", level: "L3 Trap" },
    { q: "Find the largest 4-digit number exactly divisible by 15, 20 and 35.", options: ["9660", "9600", "9720", "9800"], answer: 0, explanation: "LCM(15,20,35)=420. Largest 4-digit multiple: 9999/420=23 remainder 339, so 9999-339=9660.", rule: "Find LCM first, then subtract (N mod LCM) from N.", trapcat: "LCM application", level: "L2 Application" },
    { q: "Find the remainder when 4^63 is divided by 7.", options: ["1", "2", "4", "6"], answer: 0, explanation: "Powers of 4 mod 7 cycle: 4^1=4,4^2=2,4^3=1, then repeat (cycle length 3). 63 mod 3=0, meaning 4^63 corresponds to the 3rd position in the cycle (4^3 mod7=1). Remainder=1.", rule: "Find the cycle length under the given modulus; reduce the exponent modulo that cycle length.", trapcat: "Cyclicity", level: "L3 Trap" },
    { q: "Simplify: sqrt(50) + sqrt(18) - sqrt(72)", options: ["2 sqrt(2)", "sqrt(2)", "3 sqrt(2)", "0"], answer: 0, explanation: "sqrt(50)=5sqrt(2), sqrt(18)=3sqrt(2), sqrt(72)=6sqrt(2). So 5sqrt(2)+3sqrt(2)-6sqrt(2) = 2 sqrt(2).", rule: "Reduce every surd to a multiple of the same root before combining.", trapcat: "Surds", level: "L2 Application" },
    { q: "The average of 9 consecutive multiples of 5 is 60. Find the largest of these numbers.", options: ["80", "75", "85", "70"], answer: 0, explanation: "For 9 evenly-spaced terms, the average equals the 5th (middle) term: 60. Largest (4 steps above middle) = 60+4x5=80.", rule: "Average of odd count of evenly-spaced terms = middle term.", trapcat: "Consecutive multiples reverse", level: "L2 Application" },
    { q: "30 litres of a mixture has milk:water=3:2, and 45 litres of another mixture has milk:water=1:2. Find the combined ratio of milk to water.", options: ["11:14", "14:11", "3:2", "1:2"], answer: 0, explanation: "Mix1: milk=18,water=12. Mix2: milk=15,water=30. Combined: milk=33,water=42=11:14 in simplest form.", rule: "Add milk-to-milk and water-to-water separately, then simplify.", trapcat: "Combine two mixtures", level: "L2 Application" },
    { q: "In a mixture of 90 litres, milk and water are in the ratio 4:1. How much water must be added to make the ratio 2:3?", options: ["90 litres", "80 litres", "100 litres", "70 litres"], answer: 0, explanation: "Milk=72L,Water=18L. Let x be added: 72/(18+x)=2/3 => 216=36+2x => x=90.", rule: "Milk stays fixed; solve for the new water amount.", trapcat: "Mixture dilution reverse", level: "L2 Application" },
    { q: "The HCF of two numbers is 15 and their LCM is 450. If one number is 75, find the other.", options: ["90", "85", "95", "80"], answer: 0, explanation: "Product = HCF x LCM = 15x450=6750. Other number = 6750/75=90.", rule: "Number1 x Number2 = HCF x LCM.", trapcat: "HCF-LCM", level: "L2 Application" },
    { q: "Sales (in units) of three products across 2 years: A:60->72, B:80->92, C:50->65. Which product had the highest percentage growth?", options: ["C", "A", "B", "All equal"], answer: 0, explanation: "Growth%: A=(12/60)x100=20%. B=(12/80)x100=15%. C=(15/50)x100=30%. C has the highest percentage growth.", rule: "Compute percentage increase for each item separately, not raw increase.", trapcat: "DI percentage comparison", level: "L2 Application" },
    { q: "Find the inradius of a right-angled triangle with sides 8 cm, 15 cm, and 17 cm (hypotenuse 17 cm).", options: ["3 cm", "4 cm", "3.5 cm", "2.5 cm"], answer: 0, explanation: "For a right triangle, inradius = (leg1+leg2-hypotenuse)/2 = (8+15-17)/2 = 6/2 = 3 cm.", rule: "Right-triangle inradius shortcut: (a+b-c)/2.", trapcat: "Geometry", level: "L2 Application" },
    { q: "A invests Rs.15,000 for 10 months, B invests Rs.20,000 for 8 months, and C invests Rs.25,000 for 6 months. If the total profit is Rs.4,600, find A's share.", options: ["Rs.1,500", "Rs.1,600", "Rs.1,400", "Rs.1,700"], answer: 0, explanation: "Capital-months: A=150000,B=160000,C=150000,total=460000. A's share=4600x(150000/460000)=1,500.", rule: "Profit shares use investment x time, not investment alone.", trapcat: "Partnership - staggered", level: "L2 Application" },
    { q: "A boat covers 45 km downstream in 3 hours. In the time it takes to cover 36 km downstream, it covers 18 km upstream. Find the speed of the stream.", options: ["3.75 km/h", "4 km/h", "3.5 km/h", "4.25 km/h"], answer: 0, explanation: "Downstream speed=45/3=15 km/h. Time for 36km downstream=36/15=2.4h. Upstream speed=18/2.4=7.5 km/h. Stream speed=(15-7.5)/2=3.75 km/h.", rule: "Derive the time from one scenario, apply it to the other before finding stream speed.", trapcat: "Boats - indirect derivation", level: "L3 Trap" },
    { q: "In a two-digit number, the sum of the digits is 9. If the digits are reversed, the new number exceeds the original by 45. Find the original number.", options: ["27", "18", "36", "45"], answer: 0, explanation: "Let tens=t,units=u. t+u=9. 9(u-t)=45 => u-t=5. Solving: u=7,t=2. Original number=27 (check: reversed=72, 72-27=45).", rule: "Set up two equations from digit sum and reversal difference.", trapcat: "Two-digit number problem", level: "L3 Trap" },
    { q: "A can complete a work in 18 days, B in 27 days. They work together for 6 days, after which A leaves and B completes the rest. If the total wage is Rs.4,500, paid in proportion to work done, find A's share.", options: ["Rs.1,500", "Rs.1,800", "Rs.1,200", "Rs.1,600"], answer: 0, explanation: "In 6 days, A completes 6/18=1/3 of the work. Wage proportional to work done: A's share=(1/3)x4500=Rs.1,500.", rule: "Wages tied to fraction of total work completed, not days worked.", trapcat: "Work + wage split", level: "L2 Application" },
    { q: "The angle of elevation of the top of a tower from a point 40 m from its base is 45 degrees. If the observer moves 10 m closer, find the new angle of elevation's tangent value (height stays the same).", options: ["4/3", "3/4", "5/4", "4/5"], answer: 0, explanation: "At 45 degrees, height=distance=40m (since tan45=1). New distance=40-10=30m. New tan(angle)=height/new distance=40/30=4/3.", rule: "Recover height from the first angle, then use it with the new distance.", trapcat: "Height and distance - two stage", level: "L3 Trap" }
  ]
},
{
  id: "oct2_m4", label: "2 Oct · GS Mock (Statement-based)", timeLimitMin: 30,
  questions: [
    { q: "Consider the following statements: 1. Article 21A makes free and compulsory education a Fundamental Right for children aged 6-14. 2. This was added by the 86th Constitutional Amendment, 2002. 3. The corresponding Fundamental Duty regarding education was added at the same time by the same amendment. Which of the above is/are correct?", options: ["1, 2 and 3", "1 and 2 only", "2 and 3 only", "1 only"], answer: 0, explanation: "All three are correct: the 86th Amendment (2002) added both Article 21A (Fundamental Right) and the corresponding 11th Fundamental Duty (Article 51A(k)) in the same amendment.", rule: "86th Amendment — Article 21A + 11th Fundamental Duty, same amendment.", trapcat: "Statement-based - Polity", level: "L3 Trap" },
    { q: "Consider the following statements: 1. The Rajya Sabha can be dissolved by the President. 2. One-third of Rajya Sabha members retire every two years. 3. A person must be at least 30 years old to be a member of the Rajya Sabha. Which of the above is/are correct?", options: ["2 and 3 only", "1, 2 and 3", "1 and 2 only", "1 only"], answer: 0, explanation: "Statements 2 and 3 are correct. Statement 1 is false — the Rajya Sabha is a permanent body and can NEVER be dissolved, unlike the Lok Sabha.", rule: "Rajya Sabha is permanent, never dissolved; minimum age 30; one-third retire every 2 years.", trapcat: "Statement-based - Polity", level: "L3 Trap" },
    { q: "Consider the following statements: 1. The Battle of Buxar (1764) was fought between the British and a combined force of Mir Qasim, Shuja-ud-Daulah, and Shah Alam II. 2. The British victory at Buxar led directly to the Treaty of Allahabad (1765). 3. The Treaty of Allahabad granted the British Diwani rights over Bengal, Bihar, and Odisha. Which of the above is/are correct?", options: ["1, 2 and 3", "1 and 2 only", "2 and 3 only", "1 only"], answer: 0, explanation: "All three statements are correct and historically well-established: Buxar (1764) was fought against this three-way alliance, leading to the Treaty of Allahabad (1765) which granted Diwani rights (revenue collection) over Bengal, Bihar and Odisha.", rule: "Battle of Buxar (1764) -> Treaty of Allahabad (1765) -> Diwani rights.", trapcat: "Statement-based - History", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Deccan Plateau is bordered by the Western Ghats and Eastern Ghats. 2. The Western Ghats are higher in elevation than the Eastern Ghats on average. 3. The Eastern Ghats are a continuous, unbroken mountain range along the eastern coast. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — the Eastern Ghats are DISCONTINUOUS and irregular, broken up by several rivers flowing into the Bay of Bengal, unlike the more continuous Western Ghats.", rule: "Western Ghats: continuous, higher. Eastern Ghats: discontinuous, lower.", trapcat: "Statement-based - Geography", level: "L2 Application" },
    { q: "Consider the following statements: 1. Repo Rate is the rate at which RBI lends to commercial banks. 2. An increase in Repo Rate generally makes loans costlier and helps control inflation. 3. Repo Rate is decided by the Union Finance Ministry, not the RBI. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — the Repo Rate is decided by the RBI's Monetary Policy Committee (MPC), not the Finance Ministry.", rule: "Repo Rate is an RBI/MPC decision, not a Finance Ministry one.", trapcat: "Statement-based - Economy", level: "L2 Application" },
    { q: "Consider the following statements: 1. Photosynthesis occurs only in the presence of sunlight. 2. Respiration occurs only in the absence of sunlight. 3. Both photosynthesis and respiration involve gas exchange. Which of the above is/are correct?", options: ["1 and 3 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 3 are correct. Statement 2 is false — respiration occurs CONTINUOUSLY in living cells, both day and night, not only in the absence of sunlight.", rule: "Photosynthesis needs light; respiration happens continuously (day and night).", trapcat: "Statement-based - Biology", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Champaran Satyagraha (1917) was Gandhi's first major movement in India. 2. It was primarily concerned with indigo cultivators being forced to grow indigo under exploitative conditions. 3. The movement took place in present-day Bihar. Which of the above is/are correct?", options: ["1, 2 and 3", "1 and 2 only", "2 and 3 only", "1 only"], answer: 0, explanation: "All three statements are correct: Champaran (1917), Gandhi's first major Indian movement, addressed indigo cultivators' exploitation under the 'Tinkathia' system in Bihar.", rule: "Champaran Satyagraha (1917) — Gandhi's first India movement, indigo cultivators, Bihar.", trapcat: "Statement-based - History", level: "L1 Direct" },
    { q: "Consider the following statements: 1. The Rann of Kutch is a salt marsh located in Gujarat. 2. It is divided into the Great Rann and the Little Rann. 3. The Rann of Kutch remains submerged in water throughout the entire year. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — the Rann of Kutch is submerged only during the monsoon/certain periods and becomes a dry salt desert for much of the year, not submerged throughout.", rule: "Rann of Kutch — seasonal submersion, not year-round.", trapcat: "Statement-based - Geography", level: "L2 Application" },
    { q: "Consider the following statements: 1. Disguised unemployment is common in the Indian agricultural sector. 2. It refers to a situation where more people are employed in a job than actually needed, with marginal productivity of extra workers being zero. 3. Disguised unemployment is easy to measure directly through official unemployment statistics. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — disguised unemployment is notoriously DIFFICULT to measure directly, since those affected appear 'employed' in official statistics despite contributing little to output.", rule: "Disguised unemployment: common in agriculture, zero marginal productivity, hard to measure directly.", trapcat: "Statement-based - Economy", level: "L2 Application" },
    { q: "Consider the following statements: 1. The pH of human blood is normally slightly alkaline, around 7.4. 2. A pH below 7 indicates an alkaline solution. 3. Gastric juice in the stomach has a highly acidic pH. Which of the above is/are correct?", options: ["1 and 3 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 3 are correct. Statement 2 is false — a pH BELOW 7 indicates an ACIDIC solution, not alkaline; alkaline solutions have pH above 7.", rule: "pH < 7 = acidic; pH > 7 = alkaline; pH = 7 = neutral.", trapcat: "Statement-based - Chemistry", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Second Round Table Conference (1931) was attended by Gandhi as the sole Congress representative. 2. It failed primarily due to disagreements over minority representation. 3. All three Round Table Conferences (1930-32) resulted in the immediate grant of full Dominion Status to India. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — none of the three Round Table Conferences resulted in an immediate grant of Dominion Status; they eventually led to the Government of India Act, 1935, a much more limited outcome.", rule: "Round Table Conferences (1930-32) did not grant Dominion Status — led to the 1935 Act instead.", trapcat: "Statement-based - History", level: "L2 Application" },
    { q: "Consider the following statements: 1. India's Exclusive Economic Zone (EEZ) extends up to 200 nautical miles from the baseline. 2. Within the EEZ, India has exclusive rights to exploit natural resources like fisheries and minerals. 3. The territorial waters of India extend up to 200 nautical miles as well, identical to the EEZ. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — territorial waters extend only up to 12 nautical miles, a much smaller zone than the 200 nautical mile EEZ; the two are not identical.", rule: "Territorial waters = 12 nautical miles; EEZ = 200 nautical miles (distinct zones).", trapcat: "Statement-based - Geography/Polity", level: "L2 Application" },
    { q: "Consider the following statements: 1. Vitamin C deficiency causes the disease Scurvy. 2. Vitamin C is water-soluble and cannot be stored in the body for long periods. 3. Citrus fruits are a poor source of Vitamin C. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — citrus fruits (oranges, lemons) are in fact one of the BEST-KNOWN sources of Vitamin C, not a poor source.", rule: "Vitamin C: water-soluble, deficiency causes Scurvy, citrus fruits are a rich source.", trapcat: "Statement-based - Nutrition", level: "L1 Direct" },
    { q: "Consider the following statements: 1. The Bhakra Nangal Dam is built on the Sutlej river. 2. It is one of the highest gravity dams in Asia. 3. The dam is located entirely within the state of Punjab. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — the Bhakra Dam is located at the Punjab-Himachal Pradesh border (in Bilaspur district, Himachal Pradesh), not entirely within Punjab.", rule: "Bhakra Dam — on Sutlej, at the Punjab-Himachal Pradesh border.", trapcat: "Statement-based - Geography", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Non-Aligned Movement (NAM) was founded in 1961 in Belgrade. 2. India, along with Yugoslavia, Egypt, Ghana, and Indonesia, were among its founding members. 3. NAM's founding principle was for member countries to formally ally with either the USA or the USSR bloc, whichever offered more aid. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false and contradicts the entire premise — NAM's founding principle was explicitly NOT to formally align with either Cold War bloc (USA or USSR), which is precisely what 'non-aligned' means.", rule: "NAM (1961, Belgrade) — explicitly non-aligned with either Cold War bloc.", trapcat: "Statement-based - International Relations", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Chipko Movement (1973) was a forest conservation movement started in Uttarakhand. 2. It involved villagers, especially women, hugging trees to prevent them from being felled. 3. Sunderlal Bahuguna and Chandi Prasad Bhatt were prominent leaders associated with this movement. Which of the above is/are correct?", options: ["1, 2 and 3", "1 and 2 only", "2 and 3 only", "1 only"], answer: 0, explanation: "All three statements are correct: the Chipko Movement (1973, then Uttar Pradesh, now Uttarakhand) involved tree-hugging protests, with Sunderlal Bahuguna and Chandi Prasad Bhatt as key leaders.", rule: "Chipko Movement (1973) — Bahuguna and Bhatt, tree-hugging forest conservation.", trapcat: "Statement-based - Environmental History", level: "L1 Direct" },
    { q: "Consider the following statements: 1. The Rajya Sabha has equal legislative power with the Lok Sabha on all matters. 2. Money Bills can only be introduced in the Lok Sabha. 3. The Rajya Sabha can only recommend changes to a Money Bill, which the Lok Sabha may accept or reject. Which of the above is/are correct?", options: ["2 and 3 only", "1, 2 and 3", "1 and 2 only", "1 only"], answer: 0, explanation: "Statements 2 and 3 are correct. Statement 1 is false — the Rajya Sabha does NOT have equal power on Money Bills specifically (a key exception to otherwise largely equal status on ordinary legislation); its role there is only recommendatory.", rule: "Rajya Sabha has near-equal power generally, but a specific, limited role on Money Bills only.", trapcat: "Statement-based - Polity", level: "L2 Application" },
    { q: "Consider the following statements: 1. Coral reefs are formed by colonies of tiny marine animals called coral polyps. 2. Corals thrive best in cold, deep ocean waters. 3. The Great Barrier Reef, the world's largest coral reef system, is located off the coast of Australia. Which of the above is/are correct?", options: ["1 and 3 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 3 are correct. Statement 2 is false — corals thrive in WARM, shallow, clear tropical waters, not cold, deep ones, which is why reefs form mainly in tropical/subtropical zones.", rule: "Coral reefs need warm, shallow, clear tropical waters — not cold, deep water.", trapcat: "Statement-based - Marine Geography", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Preamble was amended once, by the 42nd Amendment (1976). 2. The Preamble is considered part of the Constitution and can be used to interpret ambiguous provisions. 3. The Preamble was the very first part of the Constitution to be drafted by the Constituent Assembly. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — the Preamble was actually one of the LAST parts finalized by the Constituent Assembly (based on the Objectives Resolution but formally adopted near the end), not the first.", rule: "Preamble amended once (42nd Amendment); finalized near the END of the drafting process, not the beginning.", trapcat: "Statement-based - Polity", level: "L2 Application" },
    { q: "Consider the following statements: 1. Diabetes mellitus is caused by insufficient insulin production or the body's ineffective use of insulin. 2. Type 1 diabetes is typically an autoimmune condition, often diagnosed in children/young adults. 3. Type 2 diabetes cannot be managed through lifestyle changes and always requires insulin injections from diagnosis. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — Type 2 diabetes CAN often be managed (at least initially) through diet, exercise, and oral medication, and does not always require insulin from the point of diagnosis.", rule: "Type 2 diabetes is often manageable via lifestyle/oral medication, unlike the false absolute claim.", trapcat: "Statement-based - Health Science", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Quit India Resolution was passed by the AICC in Bombay on 8 August 1942. 2. Gandhi gave the 'Do or Die' call during this movement. 3. Most major Congress leaders remained free throughout the Quit India Movement to coordinate protests nationally. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — most major Congress leaders (including Gandhi and Nehru) were ARRESTED almost immediately after the movement's launch, leaving it largely leaderless and spontaneous at the local level.", rule: "Quit India (Aug 1942) — most top leaders arrested immediately, not left free to coordinate.", trapcat: "Statement-based - History", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Reserve Bank of India was nationalised in 1949. 2. Prior to nationalisation, RBI was a privately owned institution since its establishment in 1935. 3. India has never had any privately-owned central bank at any point in its history. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false and directly contradicts statement 2 — RBI WAS privately owned (with private shareholders) from 1935 until its nationalisation in 1949, so India did have a privately-owned central bank for that period.", rule: "RBI: private shareholding 1935-1949, then nationalised.", trapcat: "Statement-based - Economy", level: "L2 Application" },
    { q: "Consider the following statements: 1. The Sundarbans, the world's largest mangrove forest, is shared between India and Bangladesh. 2. It is home to the Royal Bengal Tiger. 3. Mangrove forests generally cannot survive in saline (salty) water conditions. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — mangroves are specifically ADAPTED to survive in saline, brackish water conditions found in tidal river deltas, which is precisely why they thrive in the Sundarbans delta.", rule: "Mangroves are salt-tolerant by adaptation, not intolerant of saline water.", trapcat: "Statement-based - Ecology", level: "L2 Application" },
    { q: "Consider the following statements: 1. India's Constitution is the longest written constitution of any sovereign country in the world. 2. It originally had 22 Parts and 8 Schedules at the time of adoption in 1949. 3. The number of Articles and Schedules has remained exactly the same since 1949, with no additions ever made. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — both Articles and Schedules have been ADDED over time through various amendments (e.g. Article 21A, the 12th Schedule), so the count has changed significantly since 1949.", rule: "Constitution's Parts/Articles/Schedules have grown via amendments since 1949, not stayed frozen.", trapcat: "Statement-based - Polity", level: "L2 Application" },
    { q: "Consider the following statements: 1. Continental drift theory was proposed by Alfred Wegener. 2. Wegener proposed that all continents were once joined together in a single supercontinent called Pangaea. 3. Wegener's theory was immediately and universally accepted by the scientific community upon publication. Which of the above is/are correct?", options: ["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"], answer: 0, explanation: "Statements 1 and 2 are correct. Statement 3 is false — Wegener's theory (1912) faced significant scientific SKEPTICISM and rejection for decades, gaining wide acceptance only later once plate tectonics theory provided a mechanism in the mid-20th century.", rule: "Wegener's continental drift theory was initially rejected, not immediately accepted.", trapcat: "Statement-based - Geology", level: "L2 Application" }
  ]
}
];
